import type { CardRecord } from "./types";

export function noteDuplicateKey(value: string): string {
  return value.replace(/<[^>]*>/g, " ").replace(/&nbsp;/gi, " ").replace(/\s+/g, " ").trim().toLocaleLowerCase();
}

export function cardsForEditedNote(
  current: CardRecord,
  noteCards: readonly CardRecord[],
  fields: Record<string, string>,
  tags: string[],
): CardRecord[] {
  return (noteCards.length ? noteCards : [current]).map((card) => ({ ...card, fields: { ...fields }, tags: [...tags] }));
}

export function cardsForNewNote(
  base: CardRecord,
  templates: readonly CardRecord[],
  nextId: () => string,
): CardRecord[] {
  return (templates.length ? templates : [base]).map((template, index) => {
    const id = index === 0 ? base.id : nextId();
    return {
      ...base,
      key: `${base.deckId}:${id}`,
      id,
      ordinal: template.ordinal,
      templateName: template.templateName,
      questionTemplate: template.questionTemplate,
      answerTemplate: template.answerTemplate,
      css: template.css,
      fields: { ...base.fields },
      tags: [...base.tags],
    };
  });
}
