import { BlobReader, BlobWriter, TextReader, Uint8ArrayReader, ZipWriter, configure } from "@zip.js/zip.js";
import initSqlJs from "sql.js";
import wasmUrl from "sql.js/dist/sql-wasm.wasm?url";
import type { CardRecord, DeckRecord } from "./types";

configure({ maxWorkers: 1, useWebWorkers: false });

function localMediaName(value: string): string | undefined {
  const name = value.trim().replace(/^['"]|['"]$/g, "");
  if (!name || /^(?:[a-z]+:|\/\/|#)/i.test(name)) return undefined;
  try { return decodeURIComponent(name).normalize("NFC"); } catch { return name.normalize("NFC"); }
}

export function referencedMediaNames(cards: readonly CardRecord[]): Set<string> {
  const names = new Set<string>();
  for (const card of cards) {
    const source = `${Object.values(card.fields).join("\n")}\n${card.questionTemplate}\n${card.answerTemplate}\n${card.css}`;
    for (const match of source.matchAll(/\[sound:([^\]]+)\]/gi)) { const name = localMediaName(match[1]); if (name) names.add(name); }
    for (const match of source.matchAll(/(?:src|href)\s*=\s*(?:"([^"]+)"|'([^']+)'|([^\s>]+))/gi)) { const name = localMediaName(match[1] ?? match[2] ?? match[3]); if (name) names.add(name); }
    for (const match of source.matchAll(/url\(\s*([^\)]+)\s*\)/gi)) { const name = localMediaName(match[1]); if (name) names.add(name); }
  }
  return names;
}

export function missingMediaNames(cards: readonly CardRecord[], available: ReadonlySet<string>): string[] {
  return [...referencedMediaNames(cards)].filter((name) => !available.has(name)).sort();
}

function stableInteger(value: string): number {
  let high = 0x811c9dc5, low = 0x9e3779b9;
  for (let index = 0; index < value.length; index += 1) {
    high = Math.imul(high ^ value.charCodeAt(index), 0x01000193) >>> 0;
    low = Math.imul(low ^ (value.charCodeAt(index) + index), 0x85ebca6b) >>> 0;
  }
  return Number(((BigInt(high) << 21n) | BigInt(low & 0x1fffff)) % 8_000_000_000_000_000n) + 1;
}

function ankiInteger(original: string, fallbackSeed: string): number {
  if (/^[1-9]\d{0,15}$/.test(original)) {
    const value = Number(original);
    if (Number.isSafeInteger(value)) return value;
  }
  return stableInteger(fallbackSeed);
}

export async function exportApkg(deck: DeckRecord, cards: readonly CardRecord[], mediaNames: readonly string[], loadMedia: (name: string) => Promise<Blob | undefined>, onProgress?: (completed: number, total: number) => void): Promise<Blob> {
  const missing = missingMediaNames(cards, new Set(mediaNames.map((name) => name.normalize("NFC"))));
  if (missing.length) throw new Error(`参照されているメディアが${missing.length}件見つかりません（${missing.slice(0, 3).join("、")}）。整合性を修復してから書き出してください。`);
  const SQL = await initSqlJs({ locateFile: () => wasmUrl });
  const db = new SQL.Database();
  db.run("CREATE TABLE col (id integer primary key, crt integer, mod integer, scm integer, ver integer, dty integer, usn integer, ls integer, conf text, models text, decks text, dconf text, tags text)");
  db.run("CREATE TABLE notes (id integer primary key, guid text, mid integer, mod integer, usn integer, tags text, flds text, sfld integer, csum integer, flags integer, data text)");
  db.run("CREATE TABLE cards (id integer primary key, nid integer, did integer, ord integer, mod integer, usn integer, type integer, queue integer, due integer, ivl integer, factor integer, reps integer, lapses integer, left integer, odue integer, odid integer, flags integer, data text)");
  db.run("CREATE TABLE revlog (id integer primary key, cid integer, usn integer, ease integer, ivl integer, lastIvl integer, factor integer, time integer, type integer)");
  db.run("CREATE TABLE graves (usn integer, oid integer, type integer)");
  const modelGroups = new Map<string, CardRecord[]>();
  for (const card of cards) modelGroups.set(card.modelId, [...(modelGroups.get(card.modelId) ?? []), card]);
  const models: Record<string, unknown> = {};
  for (const [modelId, related] of modelGroups) {
    const first = related[0]; const numericId = ankiInteger(modelId, `model:${deck.id}:${modelId}`);
    const templates = [...new Map(related.map((card) => [card.ordinal, card])).values()].sort((a, b) => a.ordinal - b.ordinal);
    models[String(numericId)] = { id: numericId, name: first.modelName, type: first.modelType, css: first.css, flds: Object.keys(first.fields).map((name, ord) => ({ name, ord })), tmpls: templates.map((card) => ({ name: card.templateName, ord: card.ordinal, qfmt: card.questionTemplate, afmt: card.answerTemplate })) };
  }
  const deckIds = new Map<string, number>(); const decks: Record<string, unknown> = {};
  for (const card of cards) if (!deckIds.has(card.sourceDeckId)) { const id = ankiInteger(card.sourceDeckId, `deck:${deck.id}:${card.sourceDeckId}`); deckIds.set(card.sourceDeckId, id); decks[String(id)] = { id, name: card.deckName }; }
  const now = Math.floor(Date.now() / 1000);
  db.run("INSERT INTO col VALUES (1,?,?,?,?,?,?,?,?,?,?,?,?)", [now, now, now, 11, 0, 0, 0, JSON.stringify({}), JSON.stringify(models), JSON.stringify(decks), JSON.stringify({}), JSON.stringify({})]);
  const notes = new Map<string, CardRecord[]>(); for (const card of cards) notes.set(card.noteId, [...(notes.get(card.noteId) ?? []), card]);
  const noteIds = new Map<string, number>();
  for (const [noteId, related] of notes) { const card = related[0]; const id = ankiInteger(noteId, `note:${deck.id}:${noteId}`); noteIds.set(noteId, id); db.run("INSERT INTO notes VALUES (?,?,?,?,?,?,?,?,?,?,?)", [id, noteId, ankiInteger(card.modelId, `model:${deck.id}:${card.modelId}`), now, -1, ` ${card.tags.join(" ")} `, Object.values(card.fields).join("\u001f"), 0, 0, 0, ""]); }
  let due = 1;
  for (const card of cards) db.run("INSERT INTO cards VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)", [ankiInteger(card.id, `card:${deck.id}:${card.id}`), noteIds.get(card.noteId), deckIds.get(card.sourceDeckId), card.ordinal, now, -1, 0, card.suspended ? -1 : 0, due++, 0, 2500, 0, 0, 0, 0, 0, 0, ""]);
  const collection = db.export(); db.close();
  const writer = new ZipWriter(new BlobWriter("application/apkg"));
  await writer.add("collection.anki2", new Uint8ArrayReader(collection));
  const mediaMap: Record<string, string> = {};
  for (let index = 0; index < mediaNames.length; index += 1) { const name = mediaNames[index]; const blob = await loadMedia(name); if (!blob) throw new Error(`メディア「${name}」を読み込めませんでした。`); mediaMap[String(index)] = name; await writer.add(String(index), new BlobReader(blob)); onProgress?.(index + 1, mediaNames.length); }
  await writer.add("media", new TextReader(JSON.stringify(mediaMap)));
  await writer.add("apkg-simulator.json", new TextReader(JSON.stringify({ formatVersion: 1, deckId: deck.id })));
  return writer.close();
}
