import type { CardRecord, ProgressRecord } from "./types";

export type CardBrowserSort = "original" | "deck" | "due" | "interval" | "ease" | "lapses";

export interface CardBrowserEntry {
  card: CardRecord;
  progress?: ProgressRecord;
  marked: boolean;
  flag?: number;
}

function plainText(value: string): string {
  return value.replace(/<[^>]*>/g, " ").replace(/&nbsp;/gi, " ").replace(/\s+/g, " ").trim().toLocaleLowerCase();
}

function queryTokens(query: string): string[] {
  return [...query.matchAll(/(?:[^\s"]+|"[^"]*")+/g)].map((match) => match[0].replaceAll('"', "")).filter(Boolean);
}

function wildcardMatches(value: string, pattern: string): boolean {
  if (!pattern.includes("*")) return value.includes(pattern);
  const escaped = pattern.replace(/[.+?^${}()|[\]\\]/g, "\\$&").replaceAll("*", ".*");
  return new RegExp(`^${escaped}$`, "iu").test(value);
}

function compareNumeric(actual: number, operator: string, expected: number): boolean {
  if (operator === "<") return actual < expected;
  if (operator === "<=") return actual <= expected;
  if (operator === ">") return actual > expected;
  if (operator === ">=") return actual >= expected;
  if (operator === "!=") return actual !== expected;
  return actual === expected;
}

export function cardBrowserStatus(entry: CardBrowserEntry, now = Date.now()): "new" | "learning" | "due" | "review" | "suspended" {
  if (entry.card.suspended || entry.progress?.schedulerState?.suspended) return "suspended";
  if (!entry.progress) return "new";
  const phase = entry.progress.schedulerState?.phase;
  if (phase === "learning" || phase === "relearning") return "learning";
  if ((entry.progress.dueAt ?? Number.POSITIVE_INFINITY) <= now) return "due";
  return "review";
}

function fieldMatches(entry: CardBrowserEntry, field: string, value: string, now: number): boolean {
  const needle = plainText(value);
  if (field === "deck") {
    const deck = plainText(entry.card.deckName);
    if (needle.includes("*")) return wildcardMatches(deck, needle);
    return deck === needle || deck.startsWith(`${needle}::`);
  }
  if (field === "tag") {
    if (needle === "none") return entry.card.tags.length === 0;
    return entry.card.tags.some((tag) => {
      const normalized = plainText(tag);
      return needle.includes("*") ? wildcardMatches(normalized, needle) : normalized === needle || normalized.startsWith(`${needle}::`);
    });
  }
  if (field === "card") return plainText(entry.card.templateName).includes(needle);
  if (field === "note") return plainText(entry.card.modelName).includes(needle);
  if (field === "nid") return entry.card.noteId === value;
  if (field === "cid") return entry.card.id === value;
  if (field === "flag") {
    const flag = Number(value);
    const current = entry.flag ?? (entry.marked ? 1 : 0);
    return Number.isInteger(flag) && flag >= 0 && flag <= 7 && current === flag;
  }
  if (field === "prop") {
    const match = needle.match(/^(due|ivl|ease|lapses)(<=|>=|!=|=|<|>)(-?\d+(?:\.\d+)?)$/);
    if (!match || !entry.progress) return false;
    const [, property, operator, rawExpected] = match;
    let expected = Number(rawExpected);
    let actual: number;
    if (property === "due") actual = Math.floor(((entry.progress.dueAt ?? Number.POSITIVE_INFINITY) - now) / 86_400_000);
    else if (property === "ivl") actual = entry.progress.schedulerState?.intervalDays ?? 0;
    else if (property === "ease") {
      actual = entry.progress.schedulerState?.easeFactor ?? 2.5;
      if (expected > 10) expected /= 100;
    } else actual = entry.progress.schedulerState?.lapses ?? entry.progress.lapseCount;
    return compareNumeric(actual, operator, expected);
  }
  if (field === "is") {
    const status = cardBrowserStatus(entry, now);
    if (needle === "marked") return entry.marked;
    if (needle === "new") return status === "new";
    if (needle === "due") return status === "due" || status === "learning";
    if (needle === "review") return status === "review" || status === "due";
    if (needle === "learn" || needle === "learning") return status === "learning";
    if (needle === "suspended") return status === "suspended";
    if (needle === "leech") return entry.progress?.schedulerState?.leech === true || entry.card.tags.some((tag) => plainText(tag) === "leech");
    return false;
  }
  return false;
}

export function cardMatchesBrowserQuery(entry: CardBrowserEntry, query: string, now = Date.now()): boolean {
  const searchable = plainText([
    entry.card.deckName,
    entry.card.modelName,
    entry.card.templateName,
    ...entry.card.tags,
    ...Object.values(entry.card.fields),
  ].join(" "));
  const matchesToken = (rawToken: string): boolean => {
    const negated = rawToken.startsWith("-") && rawToken.length > 1;
    const token = negated ? rawToken.slice(1) : rawToken;
    const separator = token.indexOf(":");
    const matched = separator > 0
      ? fieldMatches(entry, token.slice(0, separator).toLocaleLowerCase(), token.slice(separator + 1), now)
      : wildcardMatches(searchable, plainText(token));
    return negated ? !matched : matched;
  };
  const groups: string[][] = [[]];
  for (const token of queryTokens(query)) {
    if (token.toLocaleUpperCase() === "OR") groups.push([]);
    else groups.at(-1)!.push(token);
  }
  return groups.some((group) => group.length > 0 && group.every(matchesToken)) || groups.every((group) => group.length === 0);
}

function numeric(value: number | undefined): number {
  return Number.isFinite(value) ? value! : Number.POSITIVE_INFINITY;
}

export function sortCardBrowserEntries(entries: readonly CardBrowserEntry[], sort: CardBrowserSort): CardBrowserEntry[] {
  if (sort === "original") return [...entries];
  return entries.map((entry, index) => ({ entry, index })).sort((left, right) => {
    const a = left.entry;
    const b = right.entry;
    let result = 0;
    if (sort === "deck") result = a.card.deckName.localeCompare(b.card.deckName, "ja", { numeric: true });
    else if (sort === "due") result = numeric(a.progress?.dueAt) - numeric(b.progress?.dueAt);
    else if (sort === "interval") result = numeric(a.progress?.schedulerState?.intervalDays) - numeric(b.progress?.schedulerState?.intervalDays);
    else if (sort === "ease") result = numeric(a.progress?.schedulerState?.easeFactor) - numeric(b.progress?.schedulerState?.easeFactor);
    else if (sort === "lapses") result = numeric(a.progress?.schedulerState?.lapses ?? a.progress?.lapseCount) - numeric(b.progress?.schedulerState?.lapses ?? b.progress?.lapseCount);
    return result || left.index - right.index;
  }).map(({ entry }) => entry);
}
