const DB_NAME = "anki-sprint-local";
const DB_VERSION = 8;
export const DATABASE_OPEN_TIMEOUT_MS = 15_000;
export const STORAGE_OPEN_TIMEOUT_MESSAGE = "端末内ストレージを開けません。Safariのプライベートブラウズを解除し、ほかのAPKG Simulator画面を閉じてから再読み込みしてください。";

let databasePromise: Promise<IDBDatabase> | undefined;

function requestValue<T>(request: IDBRequest<T>): Promise<T> {
  return new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error ?? new Error("IndexedDB request failed"));
  });
}

function transactionDone(transaction: IDBTransaction): Promise<void> {
  return new Promise((resolve, reject) => {
    transaction.oncomplete = () => resolve();
    transaction.onerror = () => reject(transaction.error ?? new Error("IndexedDB transaction failed"));
    transaction.onabort = () => reject(transaction.error ?? new Error("IndexedDB transaction aborted"));
  });
}

export function openDatabase(): Promise<IDBDatabase> {
  if (databasePromise) return databasePromise;
  if (typeof indexedDB === "undefined") return Promise.reject(new Error(STORAGE_OPEN_TIMEOUT_MESSAGE));

  databasePromise = new Promise((resolve, reject) => {
    let abandoned = false;
    let settled = false;
    let timeout: ReturnType<typeof setTimeout> | undefined;
    const rejectOpen = (error: Error) => {
      if (settled) return;
      settled = true;
      abandoned = true;
      if (timeout !== undefined) clearTimeout(timeout);
      databasePromise = undefined;
      reject(error);
    };
    let request: IDBOpenDBRequest;
    try {
      request = indexedDB.open(DB_NAME, DB_VERSION);
    } catch (error) {
      rejectOpen(error instanceof Error ? error : new Error(STORAGE_OPEN_TIMEOUT_MESSAGE));
      return;
    }
    timeout = setTimeout(() => {
      rejectOpen(new Error(STORAGE_OPEN_TIMEOUT_MESSAGE));
    }, DATABASE_OPEN_TIMEOUT_MS);
    request.onupgradeneeded = () => {
      if (abandoned) {
        request.transaction?.abort();
        return;
      }
      const db = request.result;

      if (!db.objectStoreNames.contains("decks")) db.createObjectStore("decks", { keyPath: "id" });
      if (!db.objectStoreNames.contains("cards")) {
        const cards = db.createObjectStore("cards", { keyPath: "key" });
        cards.createIndex("deckId", "deckId", { unique: false });
      }
      if (!db.objectStoreNames.contains("media")) {
        const media = db.createObjectStore("media", { keyPath: "key" });
        media.createIndex("deckId", "deckId", { unique: false });
      }
      if (!db.objectStoreNames.contains("reviews")) {
        const reviews = db.createObjectStore("reviews", { keyPath: "id", autoIncrement: true });
        reviews.createIndex("deckId", "deckId", { unique: false });
        reviews.createIndex("deckCard", ["deckId", "cardId"], { unique: false });
      }
      if (!db.objectStoreNames.contains("progress")) {
        const progress = db.createObjectStore("progress", { keyPath: "key" });
        progress.createIndex("deckId", "deckId", { unique: false });
      }
      if (!db.objectStoreNames.contains("settings")) db.createObjectStore("settings", { keyPath: "key" });
      if (!db.objectStoreNames.contains("sessions")) db.createObjectStore("sessions", { keyPath: "deckId" });
      if (!db.objectStoreNames.contains("imports")) db.createObjectStore("imports", { keyPath: "deckId" });
      if (!db.objectStoreNames.contains("reviewFlags")) {
        const reviewFlags = db.createObjectStore("reviewFlags", { keyPath: "key" });
        reviewFlags.createIndex("deckId", "deckId", { unique: false });
      }
      if (!db.objectStoreNames.contains("dailyNew")) db.createObjectStore("dailyNew", { keyPath: "deckId" });
      if (!db.objectStoreNames.contains("dailyReview")) db.createObjectStore("dailyReview", { keyPath: "deckId" });
      if (!db.objectStoreNames.contains("todayOnlyLimits")) {
        const todayOnlyLimits = db.createObjectStore("todayOnlyLimits", { keyPath: "scopeKey" });
        todayOnlyLimits.createIndex("deckId", "deckId", { unique: false });
      }
      if (!db.objectStoreNames.contains("backups")) {
        const backups = db.createObjectStore("backups", { keyPath: "id" });
        backups.createIndex("createdAt", "createdAt", { unique: false });
      }
    };
    request.onsuccess = () => {
      const db = request.result;
      if (abandoned) {
        db.close();
        return;
      }
      if (settled) {
        db.close();
        return;
      }
      settled = true;
      if (timeout !== undefined) clearTimeout(timeout);
      db.onversionchange = () => {
        db.close();
        databasePromise = undefined;
      };
      db.onclose = () => {
        databasePromise = undefined;
      };
      resolve(db);
    };
    request.onerror = () => {
      rejectOpen(request.error ?? new Error("IndexedDB could not be opened"));
    };
    request.onblocked = () => {
      rejectOpen(new Error("別の画面がデータベースを使用中です。ほかの画面を閉じてください。"));
    };
  });

  return databasePromise;
}

export async function getDecks(): Promise<DeckRecord[]> {
  const db = await openDatabase();
  const transaction = db.transaction("decks", "readonly");
  const values = await requestValue(transaction.objectStore("decks").getAll() as IDBRequest<DeckRecord[]>);
  return values.sort(compareDeckNames);
}

function aggregateReviewIndex(index: IDBIndex, deckId: string): Promise<{ count: number; correct: number }> {
  return new Promise((resolve, reject) => {
    let count = 0;
    let correct = 0;
    const request = index.openCursor(IDBKeyRange.only(deckId));
    request.onsuccess = () => {
      const cursor = request.result;
      if (!cursor) {
        resolve({ count, correct });
        return;
      }
      const review = cursor.value as ReviewRecord;
      count += 1;
      if (review.grade !== "again") correct += 1;
      cursor.continue();
    };
    request.onerror = () => reject(request.error ?? new Error("回答履歴を検査できませんでした。"));
  });
}

function aggregateProgressIndex(index: IDBIndex, deckId: string): Promise<{ count: number; correct: number; records: number }> {
  return new Promise((resolve, reject) => {
    let count = 0;
    let correct = 0;
    let records = 0;
    const request = index.openCursor(IDBKeyRange.only(deckId));
    request.onsuccess = () => {
      const cursor = request.result;
      if (!cursor) {
        resolve({ count, correct, records });
        return;
      }
      const progress = cursor.value as ProgressRecord;
      count += progress.reviewCount;
      correct += progress.correctCount;
      records += 1;
      cursor.continue();
    };
    request.onerror = () => reject(request.error ?? new Error("カード進捗を検査できませんでした。"));
  });
}

export async function scanDatabaseIntegrity(): Promise<DatabaseIntegrityReport> {
  const db = await openDatabase();
  const decks = await getDecks();
  const storeNames = ["cards", "media", "reviews", "progress", "sessions"];
  const transaction = db.transaction(storeNames, "readonly");
  const cardIndex = transaction.objectStore("cards").index("deckId");
  const mediaIndex = transaction.objectStore("media").index("deckId");
  const reviewIndex = transaction.objectStore("reviews").index("deckId");
  const progressIndex = transaction.objectStore("progress").index("deckId");
  const sessionsRequest = requestValue(transaction.objectStore("sessions").getAll() as IDBRequest<SavedSessionRecord[]>);
  const snapshots = await Promise.all(decks.map(async (deck): Promise<DeckIntegritySnapshot & { progressRecords: number }> => {
    const [actualCardCount, actualMediaCount, reviews, progress] = await Promise.all([
      requestValue(cardIndex.count(IDBKeyRange.only(deck.id))),
      requestValue(mediaIndex.count(IDBKeyRange.only(deck.id))),
      aggregateReviewIndex(reviewIndex, deck.id),
      aggregateProgressIndex(progressIndex, deck.id),
    ]);
    return {
      deckId: deck.id,
      deckName: deck.name,
      storedCardCount: deck.cardCount,
      actualCardCount,
      storedMediaCount: deck.mediaCount,
      actualMediaCount,
      storedReviewCount: deck.reviewCount,
      actualReviewCount: reviews.count,
      storedCorrectCount: deck.correctCount,
      actualCorrectCount: reviews.correct,
      progressReviewCount: progress.count,
      progressCorrectCount: progress.correct,
      progressRecords: progress.records,
    };
  }));
  const sessions = await sessionsRequest;
  await transactionDone(transaction);
  const deckIds = new Set(decks.map((deck) => deck.id));
  const issues = snapshots.flatMap(deckIntegrityIssues);
  for (const saved of sessions) {
    if (deckIds.has(saved.deckId)) continue;
    issues.push({
      code: "orphan-session",
      severity: "error",
      deckId: saved.deckId,
      deckName: saved.deckId,
      message: "削除済みデッキの途中セッションが残っています",
      repairable: false,
    });
  }
  return {
    checkedAt: Date.now(),
    databaseVersion: db.version,
    deckCount: decks.length,
    cardCount: snapshots.reduce((sum, item) => sum + item.actualCardCount, 0),
    mediaCount: snapshots.reduce((sum, item) => sum + item.actualMediaCount, 0),
    reviewCount: snapshots.reduce((sum, item) => sum + item.actualReviewCount, 0),
    progressCount: snapshots.reduce((sum, item) => sum + item.progressRecords, 0),
    issues,
    decks: snapshots,
  };
}

export async function repairDatabaseMetadata(): Promise<DatabaseIntegrityReport> {
  const report = await scanDatabaseIntegrity();
  const repairableDecks = new Map(
    report.decks
      .filter((deck) => deckIntegrityIssues(deck).some((issue) => issue.repairable))
      .map((deck) => [deck.deckId, deck]),
  );
  if (!repairableDecks.size) return report;
  const db = await openDatabase();
  const transaction = db.transaction("decks", "readwrite");
  await new Promise<void>((resolve, reject) => {
    const request = transaction.objectStore("decks").openCursor();
    request.onsuccess = () => {
      const cursor = request.result;
      if (!cursor) {
        resolve();
        return;
      }
      const deck = cursor.value as DeckRecord;
      const actual = repairableDecks.get(deck.id);
      if (actual) cursor.update({
        ...deck,
        cardCount: actual.actualCardCount,
        mediaCount: actual.actualMediaCount,
        reviewCount: actual.actualReviewCount,
        correctCount: actual.actualCorrectCount,
      });
      cursor.continue();
    };
    request.onerror = () => reject(request.error ?? new Error("デッキ集計を修復できませんでした。"));
  });
  await transactionDone(transaction);
  return scanDatabaseIntegrity();
}

