/** Keeps a card edit and any newly attached local media in one IndexedDB commit. */
export async function putCardsAndMedia(cards: CardRecord[], media: MediaRecord[]): Promise<void> {
  if (!cards.length && !media.length) return;
  const db = await openDatabase();
  const transaction = db.transaction(["cards", "media"], "readwrite");
  const cardStore = transaction.objectStore("cards");
  const mediaStore = transaction.objectStore("media");
  for (const card of cards) cardStore.put(card);
  for (const record of media) mediaStore.put(record);
  await transactionDone(transaction);
}

export async function updateModelCardTemplate(
  deckId: string,
  modelId: string,
  ordinal: number,
  template: Pick<CardRecord, "questionTemplate" | "answerTemplate" | "css">,
): Promise<number> {
  const db = await openDatabase();
  const transaction = db.transaction("cards", "readwrite");
  const request = transaction.objectStore("cards").index("deckId").openCursor(IDBKeyRange.only(deckId));
  let updated = 0;
  await new Promise<void>((resolve, reject) => {
    request.onsuccess = () => {
      const cursor = request.result;
      if (!cursor) { resolve(); return; }
      const card = cursor.value as CardRecord;
      if (card.modelId === modelId && card.ordinal === ordinal) {
        cursor.update({ ...card, ...template });
        updated += 1;
      }
      cursor.continue();
    };
    request.onerror = () => reject(request.error ?? new Error("カードテンプレートを保存できませんでした。"));
  });
  await transactionDone(transaction);
  return updated;
}

