/** Treats cards with the same noteId as one Anki note without rewriting legacy records. */
export async function getNoteCards(deckId: string, noteId: string): Promise<CardRecord[]> {
  const db = await openDatabase();
  const transaction = db.transaction("cards", "readonly");
  const request = transaction.objectStore("cards").index("deckId").openCursor(IDBKeyRange.only(deckId));
  const cards: CardRecord[] = [];
  await new Promise<void>((resolve, reject) => {
    request.onsuccess = () => {
      const cursor = request.result;
      if (!cursor) { resolve(); return; }
      const card = cursor.value as CardRecord;
      if (card.noteId === noteId) cards.push(card);
      cursor.continue();
    };
    request.onerror = () => reject(request.error ?? new Error("ノートを読み込めませんでした。"));
  });
  return cards.sort((a, b) => a.ordinal - b.ordinal);
}

/** Returns one representative for every card template in a note type. */
export async function getModelCardTemplates(deckId: string, modelId: string): Promise<CardRecord[]> {
  const db = await openDatabase();
  const transaction = db.transaction("cards", "readonly");
  const request = transaction.objectStore("cards").index("deckId").openCursor(IDBKeyRange.only(deckId));
  const templates = new Map<number, CardRecord>();
  await new Promise<void>((resolve, reject) => {
    request.onsuccess = () => {
      const cursor = request.result;
      if (!cursor) { resolve(); return; }
      const card = cursor.value as CardRecord;
      if (card.modelId === modelId && !templates.has(card.ordinal)) templates.set(card.ordinal, card);
      cursor.continue();
    };
    request.onerror = () => reject(request.error ?? new Error("カードテンプレートを読み込めませんでした。"));
  });
  return [...templates.values()].sort((a, b) => a.ordinal - b.ordinal);
}

export async function getDeckNoteTypes(deckId: string): Promise<CardRecord[]> {
  const db = await openDatabase();
  const transaction = db.transaction("cards", "readonly");
  const request = transaction.objectStore("cards").index("deckId").openCursor(IDBKeyRange.only(deckId));
  const noteTypes = new Map<string, CardRecord>();
  await new Promise<void>((resolve, reject) => {
    request.onsuccess = () => {
      const cursor = request.result;
      if (!cursor) { resolve(); return; }
      const card = cursor.value as CardRecord;
      const existing = noteTypes.get(card.modelId);
      if (!existing || card.ordinal < existing.ordinal) noteTypes.set(card.modelId, card);
      cursor.continue();
    };
    request.onerror = () => reject(request.error ?? new Error("ノートタイプを読み込めませんでした。"));
  });
  return [...noteTypes.values()].sort((a, b) => a.modelName.localeCompare(b.modelName, "ja", { numeric: true }));
}

export async function hasDuplicateNote(deckId: string, firstFieldValue: string, excludeNoteId?: string): Promise<boolean> {
  const key = noteDuplicateKey(firstFieldValue);
  if (!key) return false;
  const db = await openDatabase();
  const transaction = db.transaction("cards", "readonly");
  const request = transaction.objectStore("cards").index("deckId").openCursor(IDBKeyRange.only(deckId));
  return new Promise<boolean>((resolve, reject) => {
    const visited = new Set<string>();
    request.onsuccess = () => {
      const cursor = request.result;
      if (!cursor) { resolve(false); return; }
      const card = cursor.value as CardRecord;
      if (card.noteId !== excludeNoteId && !visited.has(card.noteId)) {
        visited.add(card.noteId);
        const first = Object.values(card.fields)[0] ?? "";
        if (noteDuplicateKey(first) === key) { resolve(true); return; }
      }
      cursor.continue();
    };
    request.onerror = () => reject(request.error ?? new Error("重複ノートを確認できませんでした。"));
  });
}

