export async function setReviewFlag(deckId: string, cardId: string, marked: boolean): Promise<void> {
  const db = await openDatabase();
  const transaction = db.transaction("reviewFlags", "readwrite");
  const store = transaction.objectStore("reviewFlags");
  const key = `${deckId}:${cardId}`;
  if (marked) store.put({ key, deckId, cardId, markedAt: Date.now(), flag: 1 } satisfies ReviewFlagRecord);
  else store.delete(key);
  await transactionDone(transaction);
}

export async function setReviewFlags(deckId: string, cardIds: readonly string[], marked: boolean): Promise<void> {
  if (!cardIds.length) return;
  const db = await openDatabase();
  const transaction = db.transaction("reviewFlags", "readwrite");
  const store = transaction.objectStore("reviewFlags");
  const markedAt = Date.now();
  for (const cardId of cardIds) {
    const key = `${deckId}:${cardId}`;
    if (marked) store.put({ key, deckId, cardId, markedAt, flag: 1 } satisfies ReviewFlagRecord);
    else store.delete(key);
  }
  await transactionDone(transaction);
}

export async function setReviewFlagColors(deckId: string, cardIds: readonly string[], flag: number): Promise<void> {
  if (!cardIds.length) return;
  const normalized = Math.min(7, Math.max(0, Math.trunc(flag)));
  const db = await openDatabase();
  const transaction = db.transaction("reviewFlags", "readwrite");
  const store = transaction.objectStore("reviewFlags");
  const markedAt = Date.now();
  for (const cardId of cardIds) {
    const key = `${deckId}:${cardId}`;
    if (normalized === 0) store.delete(key);
    else store.put({ key, deckId, cardId, markedAt, flag: normalized } satisfies ReviewFlagRecord);
  }
  await transactionDone(transaction);
}

export async function setCardsSuspended(deckId: string, cardIds: readonly string[], suspended: boolean): Promise<void> {
  if (!cardIds.length) return;
  const db = await openDatabase();
  const transaction = db.transaction(["cards", "progress"], "readwrite");
  const cardStore = transaction.objectStore("cards");
  const progressStore = transaction.objectStore("progress");
  const records = await Promise.all(cardIds.map(async (cardId) => {
    const key = `${deckId}:${cardId}`;
    const [card, progress] = await Promise.all([
      requestValue(cardStore.get(key) as IDBRequest<CardRecord | undefined>),
      requestValue(progressStore.get(key) as IDBRequest<ProgressRecord | undefined>),
    ]);
    return { card, progress };
  }));
  for (const { card, progress } of records) {
    if (card) cardStore.put({ ...card, suspended });
    if (progress?.schedulerState) {
      progressStore.put({
        ...progress,
        schedulerState: { ...progress.schedulerState, suspended },
      });
    }
  }
  await transactionDone(transaction);
}

export async function updateCardsTags(deckId: string, cardIds: readonly string[], tags: readonly string[], remove: boolean): Promise<void> {
  if (!cardIds.length || !tags.length) return;
  const normalized = [...new Set(tags.map((tag) => tag.trim()).filter(Boolean))];
  const db = await openDatabase();
  const transaction = db.transaction("cards", "readwrite");
  const store = transaction.objectStore("cards");
  for (const cardId of cardIds) {
    const card = await requestValue(store.get(`${deckId}:${cardId}`) as IDBRequest<CardRecord | undefined>);
    if (!card) continue;
    const nextTags = remove
      ? card.tags.filter((tag) => !normalized.includes(tag))
      : [...new Set([...card.tags, ...normalized])];
    store.put({ ...card, tags: nextTags });
  }
  await transactionDone(transaction);
}

export async function deleteCardsAndHistory(deckId: string, cardIds: readonly string[]): Promise<number> {
  const uniqueIds = [...new Set(cardIds)];
  if (!uniqueIds.length) return 0;
  const db = await openDatabase();
  const transaction = db.transaction(["decks", "cards", "reviews", "progress", "reviewFlags", "sessions"], "readwrite");
  const cardStore = transaction.objectStore("cards");
  const reviewIndex = transaction.objectStore("reviews").index("deckCard");
  let deleted = 0;
  const reviewDeletes: Promise<void>[] = [];
  for (const cardId of uniqueIds) {
    const key = `${deckId}:${cardId}`;
    const existing = await requestValue(cardStore.get(key) as IDBRequest<CardRecord | undefined>);
    if (!existing) continue;
    deleted += 1;
    cardStore.delete(key);
    transaction.objectStore("progress").delete(key);
    transaction.objectStore("reviewFlags").delete(key);
    reviewDeletes.push(new Promise<void>((resolve, reject) => {
      const request = reviewIndex.openCursor(IDBKeyRange.only([deckId, cardId]));
      request.onsuccess = () => {
        const cursor = request.result;
        if (!cursor) { resolve(); return; }
        cursor.delete();
        cursor.continue();
      };
      request.onerror = () => reject(request.error ?? new Error("回答履歴を削除できませんでした。"));
    }));
  }
  await Promise.all(reviewDeletes);
  const deck = await requestValue(transaction.objectStore("decks").get(deckId) as IDBRequest<DeckRecord | undefined>);
  if (deck && deleted) transaction.objectStore("decks").put({ ...deck, cardCount: Math.max(0, deck.cardCount - deleted) });
  transaction.objectStore("sessions").delete(deckId);
  await transactionDone(transaction);
  return deleted;
}

