import type { CardRecord, ProgressRecord, ReviewRecord } from "./types";

export interface DeckStatistics {
  total: number;
  newCards: number;
  learning: number;
  due: number;
  future: number;
  suspended: number;
  mature: number;
  reviews: number;
  accuracy: number;
  averageSeconds: number;
  daily: Array<{ day: string; count: number }>;
}

export function calculateDeckStatistics(
  cards: readonly CardRecord[],
  progressRecords: readonly ProgressRecord[],
  reviews: readonly ReviewRecord[],
  now = Date.now(),
  days = 14,
): DeckStatistics {
  const progress = new Map(progressRecords.map((item) => [item.cardId, item]));
  let newCards = 0, learning = 0, due = 0, future = 0, suspended = 0, mature = 0;
  for (const card of cards) {
    const item = progress.get(card.id);
    if (card.suspended || item?.schedulerState?.suspended) { suspended += 1; continue; }
    if (!item) { newCards += 1; continue; }
    if (item.schedulerState?.phase === "learning" || item.schedulerState?.phase === "relearning") learning += 1;
    else if ((item.dueAt ?? Number.POSITIVE_INFINITY) <= now) due += 1;
    else future += 1;
    if ((item.schedulerState?.intervalDays ?? 0) >= 21) mature += 1;
  }
  const correct = reviews.filter((review) => review.grade !== "again").length;
  const averageSeconds = reviews.length ? reviews.reduce((sum, review) => sum + review.elapsedMs, 0) / reviews.length / 1000 : 0;
  const daily = Array.from({ length: days }, (_, offset) => {
    const date = new Date(now);
    date.setHours(0, 0, 0, 0);
    date.setDate(date.getDate() - (days - offset - 1));
    const next = new Date(date); next.setDate(next.getDate() + 1);
    return { day: `${date.getMonth() + 1}/${date.getDate()}`, count: reviews.filter((review) => review.reviewedAt >= date.getTime() && review.reviewedAt < next.getTime()).length };
  });
  return {
    total: cards.length, newCards, learning, due, future, suspended, mature,
    reviews: reviews.length,
    accuracy: reviews.length ? Math.round((correct / reviews.length) * 100) : 0,
    averageSeconds,
    daily,
  };
}
