export interface ViewportDiagnosticRecord {
  at: string;
  reason: string;
  window: { inner: string; outer: string; devicePixelRatio: number };
  document: { client: string; scroll: string };
  visualViewport: { size: string; offset: string; scale: number } | null;
  screen: { size: string; available: string; orientation: string; angle: number };
  app: { size: string; position: string } | null;
  study: { size: string; position: string } | null;
  mode: { standalone: boolean; fullscreen: boolean; displayMode: string };
}

const MAX_RECORDS = 40;
const records: ViewportDiagnosticRecord[] = [];

function size(width: number, height: number): string {
  return `${Math.round(width)}x${Math.round(height)}`;
}

function rect(element: Element | null): { size: string; position: string } | null {
  if (!element) return null;
  const value = element.getBoundingClientRect();
  return {
    size: size(value.width, value.height),
    position: `${Math.round(value.left)},${Math.round(value.top)}`,
  };
}

function displayMode(): string {
  for (const mode of ["fullscreen", "standalone", "minimal-ui", "browser"]) {
    if (window.matchMedia?.(`(display-mode: ${mode})`).matches) return mode;
  }
  return "unknown";
}

export function recordViewportDiagnostic(reason: string): ViewportDiagnosticRecord {
  const viewport = window.visualViewport;
  const orientation = window.screen.orientation;
  const standalone = Boolean((navigator as Navigator & { standalone?: boolean }).standalone);
  const record: ViewportDiagnosticRecord = {
    at: new Date().toISOString(),
    reason,
    window: {
      inner: size(window.innerWidth, window.innerHeight),
      outer: size(window.outerWidth, window.outerHeight),
      devicePixelRatio: window.devicePixelRatio,
    },
    document: {
      client: size(document.documentElement.clientWidth, document.documentElement.clientHeight),
      scroll: size(document.documentElement.scrollWidth, document.documentElement.scrollHeight),
    },
    visualViewport: viewport ? {
      size: size(viewport.width, viewport.height),
      offset: `${Math.round(viewport.offsetLeft)},${Math.round(viewport.offsetTop)}`,
      scale: viewport.scale,
    } : null,
    screen: {
      size: size(window.screen.width, window.screen.height),
      available: size(window.screen.availWidth, window.screen.availHeight),
      orientation: orientation?.type ?? "unknown",
      angle: orientation?.angle ?? 0,
    },
    app: rect(document.querySelector("#app")),
    study: rect(document.querySelector(".study-screen")),
    mode: {
      standalone,
      fullscreen: Boolean(document.fullscreenElement || (document as Document & { webkitFullscreenElement?: Element }).webkitFullscreenElement),
      displayMode: displayMode(),
    },
  };
  records.push(record);
  if (records.length > MAX_RECORDS) records.splice(0, records.length - MAX_RECORDS);
  return record;
}

export function viewportDiagnosticReport(version: string): string {
  const payload = {
    appVersion: version,
    userAgent: navigator.userAgent,
    platform: navigator.platform,
    maxTouchPoints: navigator.maxTouchPoints,
    records,
  };
  return JSON.stringify(payload, null, 2);
}

export function resetViewportDiagnostics(): void {
  records.length = 0;
}
