const VERSION_PATTERN = /const\s+APP_VERSION\s*=\s*["'](v[^"']+)["']/;

export function publishedServiceWorkerVersion(source: string): string | undefined {
  return VERSION_PATTERN.exec(source)?.[1];
}

export function releaseServiceWorkerUrl(baseUrl: string, version: string): string {
  const url = new URL("./service-worker.js", baseUrl);
  url.searchParams.set("release", version);
  return url.href;
}

export function compareAppVersions(left: string, right: string): number {
  const leftParts = left.replace(/^v/i, "").split(".").map((part) => Number.parseInt(part, 10) || 0);
  const rightParts = right.replace(/^v/i, "").split(".").map((part) => Number.parseInt(part, 10) || 0);
  for (let index = 0; index < Math.max(leftParts.length, rightParts.length); index += 1) {
    const difference = (leftParts[index] ?? 0) - (rightParts[index] ?? 0);
    if (difference) return Math.sign(difference);
  }
  return 0;
}

export function isPublishedVersionNewer(current: string, published: string): boolean {
  return compareAppVersions(published, current) > 0;
}
