import {
  BlobReader,
  BlobWriter,
  Uint8ArrayWriter,
  ZipReader,
  configure,
  type Entry,
  type FileEntry,
} from "@zip.js/zip.js";
import { Decompress } from "fzstd";
import initSqlJs, { type Database, type SqlJsStatic, type SqlValue } from "sql.js";
import wasmUrl from "sql.js/dist/sql-wasm.wasm?url";
import {
  decompressZstd,
  parseLegacyMediaMap,
  parseModernMediaMap,
  parseModernNotetypeConfig,
  parseModernTemplateConfig,
} from "./ankiFormat";
import {
  completeImport,
  deleteImportJob,
  deletePartialImport,
  getDeck,
  getDeckByFileFingerprint,
  getImportJob,
  putCardsWithImportCheckpoint,
  putDeck,
  putImportJob,
  putMediaBatchWithImportCheckpoint,
} from "./db";
import type { CardRecord, DeckRecord, ImportJobRecord, MediaRecord, SubdeckSummary } from "./types";

interface AnkiField {
  name: string;
  ord: number;
}

interface AnkiTemplate {
  name?: string;
  ord?: number;
  qfmt?: string;
  afmt?: string;
}

interface AnkiModel {
  name?: string;
  type?: number;
  css?: string;
  flds?: AnkiField[];
  tmpls?: AnkiTemplate[];
}

interface AnkiDeck {
  name?: string;
}

interface ImportProgress {
  phase: "opening" | "database" | "cards" | "media" | "saving";
  completed: number;
  total: number;
  message: string;
  warning?: string;
}

export type ImportProgressHandler = (progress: ImportProgress) => void;

export interface ImportResult {
  deck: DeckRecord;
  outcome: "imported" | "resumed" | "existing";
}

const MAX_DATABASE_BYTES = 400_000_000;
const MAX_MEDIA_MAP_BYTES = 64_000_000;
const MAX_ZSTD_MEDIA_BYTES = 2_000_000_000;
const CARD_BATCH_MAX_ITEMS = 2_000;
const CARD_BATCH_MAX_BYTES = 16_000_000;
// Benchmarked on the supplied 1.118GB package. Larger batches retained too
// many decoded Blobs and were slower in WebKit, so keep the proven size.
const MEDIA_BATCH_MAX_ITEMS = 8;
const MEDIA_BATCH_MAX_BYTES = 32_000_000;
const RESPONSIVE_YIELD_INTERVAL_MS = 120;

configure({ maxWorkers: 1, useWebWorkers: false });

let sqlPromise: Promise<SqlJsStatic> | undefined;

function getSql(): Promise<SqlJsStatic> {
  if (!sqlPromise) {
    sqlPromise = initSqlJs({ locateFile: () => wasmUrl }).catch((error: unknown) => {
      // A transient Wasm allocation/initialization failure must not poison all
      // later import attempts until the PWA is force-closed.
      sqlPromise = undefined;
      throw error;
    });
  }
  return sqlPromise;
}

function firstRow(db: Database, sql: string): SqlValue[] {
  const result = db.exec(sql)[0];
  if (!result?.values.length) throw new Error("Ankiデータベースに必要な情報がありません。");
  return result.values[0];
}

function rows(db: Database, sql: string): SqlValue[][] {
  return db.exec(sql)[0]?.values ?? [];
}

function asString(value: SqlValue): string {
  return typeof value === "string" ? value : String(value ?? "");
}

function asBytes(value: SqlValue): Uint8Array {
  if (value instanceof Uint8Array) return value;
  throw new Error("Ankiデータベース内の設定形式を読み取れません。");
}

function parseJsonMap<T>(value: SqlValue, label: string): Record<string, T> {
  try {
    const parsed = JSON.parse(asString(value)) as unknown;
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) throw new Error("not a map");
    return parsed as Record<string, T>;
  } catch {
    throw new Error(`${label}の解析に失敗しました。この.apkg形式には対応していない可能性があります。`);
  }
}

function baseName(fileName: string): string {
  return fileName.replace(/\.apkg$/i, "").trim() || "Ankiデッキ";
}

function safeMediaName(value: string): string | undefined {
  const normalized = value.normalize("NFC").replaceAll("\\", "/");
  if (!normalized || normalized.includes("\0") || normalized.startsWith("/") || normalized.split("/").includes("..")) {
    return undefined;
  }
  return normalized;
}

function mimeType(name: string): string {
  const extension = name.split(".").pop()?.toLowerCase() ?? "";
  const types: Record<string, string> = {
    apng: "image/apng",
    avif: "image/avif",
    bmp: "image/bmp",
    gif: "image/gif",
    jpeg: "image/jpeg",
    jpg: "image/jpeg",
    png: "image/png",
    svg: "image/svg+xml",
    webp: "image/webp",
    mp3: "audio/mpeg",
    m4a: "audio/mp4",
    ogg: "audio/ogg",
    opus: "audio/ogg",
    wav: "audio/wav",
    aac: "audio/aac",
    flac: "audio/flac",
    mp4: "video/mp4",
    m4v: "video/mp4",
    webm: "video/webm",
    mov: "video/quicktime",
    ttf: "font/ttf",
    otf: "font/otf",
    woff: "font/woff",
    woff2: "font/woff2",
  };
  return types[extension] ?? "application/octet-stream";
}

async function sha256(buffer: ArrayBuffer): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", buffer);
  return [...new Uint8Array(digest)].map((byte) => byte.toString(16).padStart(2, "0")).join("");
}

function formatBytes(bytes: number): string {
  if (bytes >= 1_000_000_000) return `${(bytes / 1_000_000_000).toFixed(2)}GB`;
  if (bytes >= 1_000_000) return `${(bytes / 1_000_000).toFixed(1)}MB`;
  return `${Math.ceil(bytes / 1000).toLocaleString()}KB`;
}

export function storageCapacityWarningForEstimate(
  requiredBytes: number,
  estimate: Pick<StorageEstimate, "quota" | "usage">,
): string | undefined {
  if (estimate.quota && estimate.usage !== undefined) {
    const available = estimate.quota - estimate.usage;
    if (requiredBytes * 1.05 > available) {
      return `保存には残り約${formatBytes(requiredBytes)}必要です。現在の推定空き容量は約${formatBytes(available)}ですが、iPadOSが読み込み中に保存領域を追加する場合があるため、このまま続行します。`;
    }
  }
  return undefined;
}

async function storageCapacityWarning(requiredBytes: number): Promise<string | undefined> {
  if (!navigator.storage?.estimate) return undefined;
  try {
    return storageCapacityWarningForEstimate(requiredBytes, await navigator.storage.estimate());
  } catch {
    // StorageManager estimates are advisory. Safari can reject this call
    // transiently; that must not block an otherwise valid local import.
    return undefined;
  }
}

function isQuotaError(error: unknown): boolean {
  return error instanceof DOMException
    ? error.name === "QuotaExceededError" || error.name === "NS_ERROR_DOM_QUOTA_REACHED"
    : error instanceof Error && /quota|disk|storage|space/i.test(error.message);
}

function isMemoryError(error: unknown): boolean {
  return error instanceof RangeError
    || (error instanceof Error && /allocation|memory|ArrayBuffer|out of bounds/i.test(error.message));
}

export function canResumeImport(
  job: ImportJobRecord,
  file: File,
  sourceFormat: DeckRecord["sourceFormat"],
  cardCount: number,
  mediaCount: number,
  expectedMediaBytes: number,
  fileFingerprint?: string,
): boolean {
  return job.fileSize === file.size
    && (!job.fileFingerprint || !fileFingerprint || job.fileFingerprint === fileFingerprint)
    && job.sourceFormat === sourceFormat
    && job.cardCount === cardCount
    && job.mediaCount === mediaCount
    && job.expectedMediaBytes === expectedMediaBytes
    && job.nextCardIndex >= 0
    && job.nextCardIndex <= cardCount
    && job.nextMediaIndex >= 0
    && job.nextMediaIndex <= mediaCount;
}

async function fingerprintFile(file: File): Promise<string> {
  const sampleBytes = 262_144;
  const middle = Math.max(0, Math.floor(file.size / 2) - Math.floor(sampleBytes / 2));
  const slices = await Promise.all([
    file.slice(0, sampleBytes).arrayBuffer(),
    file.slice(middle, middle + sampleBytes).arrayBuffer(),
    file.slice(Math.max(0, file.size - sampleBytes)).arrayBuffer(),
  ]);
  const metadata = new TextEncoder().encode(`apkg:${file.size}:`);
  const totalBytes = metadata.byteLength + slices.reduce((total, slice) => total + slice.byteLength, 0);
  const sample = new Uint8Array(totalBytes);
  sample.set(metadata, 0);
  let offset = metadata.byteLength;
  for (const slice of slices) {
    sample.set(new Uint8Array(slice), offset);
    offset += slice.byteLength;
  }
  return sha256(sample.buffer);
}

function fileEntries(entries: Entry[]): Map<string, FileEntry> {
  const files = new Map<string, FileEntry>();
  for (const entry of entries) {
    if (entry.directory) continue;
    if (files.has(entry.filename)) throw new Error(`APKG内で「${entry.filename}」が重複しています。ファイルをAnkiから再度書き出してください。`);
    files.set(entry.filename, entry);
  }
  return files;
}

async function entryBytes(entry: FileEntry, maximumBytes: number, label: string): Promise<Uint8Array> {
  if (entry.uncompressedSize > maximumBytes) throw new Error(`${label}が${formatBytes(maximumBytes)}を超えています。`);
  const bytes = await entry.getData(new Uint8ArrayWriter(), { useWebWorkers: false });
  if (bytes.byteLength > maximumBytes) throw new Error(`${label}が${formatBytes(maximumBytes)}を超えています。`);
  return bytes;
}

async function deckFingerprint(collectionBytes: Uint8Array, collectionName: string): Promise<string> {
  const sampleBytes = 1_048_576;
  const middle = Math.max(0, Math.floor(collectionBytes.byteLength / 2) - Math.floor(sampleBytes / 2));
  const metadata = new TextEncoder().encode(`${collectionName}:${collectionBytes.byteLength}:`);
  const parts = [
    metadata,
    collectionBytes.subarray(0, sampleBytes),
    collectionBytes.subarray(middle, middle + sampleBytes),
    collectionBytes.subarray(Math.max(0, collectionBytes.byteLength - sampleBytes)),
  ];
  const sample = new Uint8Array(parts.reduce((total, part) => total + part.byteLength, 0));
  let offset = 0;
  for (const part of parts) {
    sample.set(part, offset);
    offset += part.byteLength;
  }
  return sha256(sample.buffer);
}

async function legacyMediaBlob(entry: FileEntry, name: string): Promise<Blob> {
  return entry.getData(new BlobWriter(mimeType(name)), { useWebWorkers: false });
}

async function modernMediaBlob(entry: FileEntry, name: string, expectedSize?: number): Promise<Blob> {
  if (expectedSize !== undefined && expectedSize > MAX_ZSTD_MEDIA_BYTES) {
    throw new Error(`「${name}」は単体で2GBを超えるため、現在のiPad用展開処理では読み込めません。`);
  }
  let outputSize = 0;
  let decoder: Decompress | undefined;
  const transform = new TransformStream<Uint8Array, Uint8Array>({
    start(controller) {
      decoder = new Decompress((chunk) => {
        outputSize += chunk.byteLength;
        if (outputSize > MAX_ZSTD_MEDIA_BYTES) throw new Error(`「${name}」の展開サイズが2GBを超えています。`);
        controller.enqueue(chunk.slice());
      });
    },
    transform(chunk) {
      decoder?.push(chunk, false);
    },
    flush() {
      decoder?.push(new Uint8Array(0), true);
    },
  });
  const blobPromise = new Response(transform.readable, {
    headers: { "Content-Type": mimeType(name) },
  }).blob();
  try {
    await entry.getData(transform.writable, { useWebWorkers: false });
    const blob = await blobPromise;
    if (expectedSize !== undefined && blob.size !== expectedSize) {
      throw new Error(`「${name}」の展開サイズがメディア一覧と一致しません。`);
    }
    return blob;
  } catch (error) {
    await blobPromise.catch(() => undefined);
    throw error;
  }
}

interface MediaImportItem {
  entry: FileEntry;
  name: string;
  compressed: boolean;
  expectedSize?: number;
}

async function collectMediaItems(
  zip: Map<string, FileEntry>,
  modernPackage: boolean,
): Promise<MediaImportItem[]> {
  const mediaEntry = zip.get("media");
  if (!mediaEntry) return [];

  const mediaItems: MediaImportItem[] = [];
  const mediaNames = new Set<string>();
  try {
    const packedMediaMap = await entryBytes(mediaEntry, MAX_MEDIA_MAP_BYTES, "メディア一覧");
    if (modernPackage) {
      const mediaMap = parseModernMediaMap(decompressZstd(packedMediaMap, MAX_MEDIA_MAP_BYTES));
      for (const mapped of mediaMap) {
        const name = safeMediaName(mapped.name);
        const entry = zip.get(mapped.zipEntryName);
        if (!name) throw new Error("メディア一覧に安全でないファイル名があります。");
        if (mapped.expectedSize !== undefined && (!Number.isSafeInteger(mapped.expectedSize) || mapped.expectedSize < 0)) {
          throw new Error(`メディア一覧にある「${name}」のサイズ情報が不正です。`);
        }
        if (!entry) throw new Error(`メディア一覧にある「${name}」の実データが見つかりません。`);
        if (mediaNames.has(name)) throw new Error(`メディア一覧に「${name}」が重複しています。`);
        mediaNames.add(name);
        mediaItems.push({ entry, name, compressed: true, expectedSize: mapped.expectedSize });
      }
    } else {
      const mediaMap = parseLegacyMediaMap(packedMediaMap);
      for (const [entryName, rawName] of Object.entries(mediaMap)) {
        const name = safeMediaName(rawName);
        const entry = zip.get(entryName);
        if (!name) throw new Error("メディア一覧に安全でないファイル名があります。");
        if (!entry) throw new Error(`メディア一覧にある「${name}」の実データが見つかりません。`);
        if (mediaNames.has(name)) throw new Error(`メディア一覧に「${name}」が重複しています。`);
        mediaNames.add(name);
        mediaItems.push({ entry, name, compressed: false });
      }
    }
  } catch (error) {
    if (isMemoryError(error)) throw error;
    if (error instanceof Error && /メディア一覧/.test(error.message)) throw error;
    throw new Error("画像・音声の一覧を解析できません。.apkgが完全に保存されているか確認してください。");
  }
  return mediaItems;
}

function cardFromDatabaseRow(
  row: SqlValue[],
  deckId: string,
  models: Record<string, AnkiModel>,
  decks: Record<string, AnkiDeck>,
): CardRecord {
  const cardId = asString(row[0]);
  const noteId = asString(row[1]);
  const sourceDeckId = asString(row[2]);
  const ordinal = Number(row[3]);
  const modelId = asString(row[5]);
  const model = models[modelId];
  if (!model) throw new Error(`カード${cardId}が参照するノートタイプ${modelId || "（不明）"}を読み取れません。`);
  const template = model.type === 1 ? model.tmpls?.[0] : model.tmpls?.[ordinal];
  if (!template) throw new Error(`カード${cardId}が参照するテンプレート${ordinal + 1}を読み取れません。`);

  const values = asString(row[7]).split("\u001f");
  const fields: Record<string, string> = {};
  for (const field of model.flds ?? []) fields[field.name] = values[field.ord] ?? "";

  return {
    key: `${deckId}:${cardId}`,
    id: cardId,
    noteId,
    deckId,
    sourceDeckId,
    deckName: decks[sourceDeckId]?.name ?? "既定",
    modelId,
    modelName: model.name ?? "カード",
    templateName: template.name ?? `カード ${ordinal + 1}`,
    ordinal,
    modelType: model.type ?? 0,
    questionTemplate: template.qfmt ?? "",
    answerTemplate: template.afmt ?? "{{FrontSide}}<hr id=answer>{{Back}}",
    css: model.css ?? "",
    fields,
    tags: asString(row[6]).trim().split(/\s+/).filter(Boolean),
    suspended: Number(row[4]) === -1,
  };
}

function approximateCardBytes(card: CardRecord): number {
  let characters = card.key.length + card.id.length + card.noteId.length + card.deckId.length
    + card.sourceDeckId.length + card.deckName.length + card.modelId.length + card.modelName.length
    + card.templateName.length + card.questionTemplate.length + card.answerTemplate.length + card.css.length;
  for (const [name, value] of Object.entries(card.fields)) characters += name.length + value.length;
  for (const tag of card.tags) characters += tag.length;
  return Math.max(1_024, characters * 2 + 512);
}

function deckNameFromNames(file: File, names: ReadonlySet<string>): string {
  const available = [...names].filter((name) => name && name !== "既定");
  if (available.length === 1) return available[0];
  if (available.length > 1) {
    const roots = [...new Set(available.map((name) => name.split("::")[0]))];
    if (roots.length === 1) return roots[0];
  }
  return baseName(file.name);
}

function subdeckSummariesFromDatabase(
  db: Database,
  decks: Record<string, AnkiDeck>,
): SubdeckSummary[] {
  const summaries: SubdeckSummary[] = [];
  const statement = db.prepare("SELECT did, COUNT(*) FROM cards GROUP BY did");
  try {
    while (statement.step()) {
      const [sourceDeckId, count] = statement.get();
      summaries.push({
        sourceDeckId: asString(sourceDeckId),
        name: decks[asString(sourceDeckId)]?.name ?? "既定",
        cardCount: Number(count),
      });
    }
  } finally {
    statement.free();
  }
  return summaries.sort((a, b) => a.name.localeCompare(b.name, "ja", { numeric: true }));
}

export interface CardImportSummary {
  job: ImportJobRecord;
  deckName: string;
  subdecks: SubdeckSummary[];
}

export async function importCardsFromDatabase(
  db: Database,
  file: File,
  deckId: string,
  models: Record<string, AnkiModel>,
  decks: Record<string, AnkiDeck>,
  expectedCardCount: number,
  initialJob: ImportJobRecord,
  onProgress: ImportProgressHandler,
  onCheckpoint: (job: ImportJobRecord) => void,
): Promise<CardImportSummary> {
  let job = initialJob;
  let processed = initialJob.nextCardIndex;
  let batch: CardRecord[] = [];
  let batchBytes = 0;
  let lastCardYieldAt = performance.now();
  const subdecks = subdeckSummariesFromDatabase(db, decks);
  const deckNames = new Set(subdecks.map((summary) => summary.name));
  const statement = db.prepare(`
    SELECT c.id, c.nid, c.did, c.ord, c.queue, n.mid, n.tags, n.flds
    FROM cards c
    LEFT JOIN notes n ON n.id = c.nid
    ORDER BY c.id
    LIMIT -1 OFFSET ${initialJob.nextCardIndex}
  `);

  const flush = async (): Promise<void> => {
    if (!batch.length) return;
    const nextJob: ImportJobRecord = { ...job, nextCardIndex: processed, updatedAt: Date.now() };
    await putCardsWithImportCheckpoint(batch, nextJob);
    job = nextJob;
    onCheckpoint(job);
    batch = [];
    batchBytes = 0;
    onProgress({
      phase: "cards",
      completed: job.nextCardIndex,
      total: expectedCardCount,
      message: `${expectedCardCount.toLocaleString()}枚のカードを保存しています`,
    });
  };

  try {
    while (statement.step()) {
      const card = cardFromDatabaseRow(statement.get(), deckId, models, decks);
      processed += 1;
      batch.push(card);
      batchBytes += approximateCardBytes(card);
      if (batch.length >= CARD_BATCH_MAX_ITEMS || batchBytes >= CARD_BATCH_MAX_BYTES) await flush();
      if (performance.now() - lastCardYieldAt >= RESPONSIVE_YIELD_INTERVAL_MS) {
        lastCardYieldAt = await yieldToBrowserIfNeeded(lastCardYieldAt);
      }
    }
    await flush();
  } finally {
    statement.free();
  }

  if (processed !== expectedCardCount || job.nextCardIndex !== expectedCardCount) {
    throw new Error(`カードデータの関連付けが不完全です（${processed.toLocaleString()} / ${expectedCardCount.toLocaleString()}枚）。APKGをAnkiから再度書き出してください。`);
  }
  return {
    job,
    deckName: deckNameFromNames(file, deckNames),
    subdecks,
  };
}

async function yieldToBrowserIfNeeded(lastYieldAt: number): Promise<number> {
  const now = performance.now();
  if (now - lastYieldAt < RESPONSIVE_YIELD_INTERVAL_MS) return lastYieldAt;
  await new Promise<void>((resolve) => {
    if (typeof requestAnimationFrame === "function") requestAnimationFrame(() => resolve());
    else setTimeout(resolve, 0);
  });
  return performance.now();
}

function modernModelsAndDecks(db: Database): { models: Record<string, AnkiModel>; decks: Record<string, AnkiDeck> } {
  const models: Record<string, AnkiModel> = {};
  for (const row of rows(db, "SELECT id, name, config FROM notetypes")) {
    const id = asString(row[0]);
    const config = parseModernNotetypeConfig(asBytes(row[2]));
    models[id] = {
      name: asString(row[1]),
      type: config.modelType,
      css: config.css,
      flds: [],
      tmpls: [],
    };
  }
  for (const row of rows(db, "SELECT ntid, ord, name FROM fields ORDER BY ntid, ord")) {
    const model = models[asString(row[0])];
    if (!model) continue;
    model.flds?.push({ ord: Number(row[1]), name: asString(row[2]) });
  }
  for (const row of rows(db, "SELECT ntid, ord, name, config FROM templates ORDER BY ntid, ord")) {
    const model = models[asString(row[0])];
    if (!model?.tmpls) continue;
    const ordinal = Number(row[1]);
    const config = parseModernTemplateConfig(asBytes(row[3]));
    model.tmpls[ordinal] = {
      ord: ordinal,
      name: asString(row[2]),
      qfmt: config.question,
      afmt: config.answer,
    };
  }

  const decks: Record<string, AnkiDeck> = {};
  for (const row of rows(db, "SELECT id, name FROM decks")) {
    decks[asString(row[0])] = { name: asString(row[1]) };
  }
  return { models, decks };
}

export async function importApkg(file: File, onProgress: ImportProgressHandler): Promise<ImportResult> {
  if (!file.name.toLowerCase().endsWith(".apkg")) throw new Error(".apkgファイルを選択してください。");
  await navigator.storage?.persist?.().catch(() => false);
  onProgress({ phase: "opening", completed: 0, total: 1, message: "ファイルを安全に開いています" });
  const fileFingerprint = await fingerprintFile(file);
  const knownDeck = await getDeckByFileFingerprint(file.size, fileFingerprint);
  if (knownDeck) return { deck: knownDeck, outcome: "existing" };

  const zipReader = new ZipReader(new BlobReader(file), { useWebWorkers: false });
  let activeJob: ImportJobRecord | undefined;
  try {
    let lastOpeningProgressAt = 0;
    const entries = await zipReader.getEntries({
      async onprogress(completed, total) {
        const now = performance.now();
        if (completed < total && now - lastOpeningProgressAt < 100) return;
        lastOpeningProgressAt = now;
        onProgress({ phase: "opening", completed, total, message: "大容量ファイルの目次を読み取っています" });
      },
    });
    const zip = fileEntries(entries);
    const collectionName: DeckRecord["sourceFormat"] | undefined = zip.has("collection.anki21b")
      ? "collection.anki21b"
      : zip.has("collection.anki21")
        ? "collection.anki21"
        : zip.has("collection.anki2")
          ? "collection.anki2"
          : undefined;
    if (!collectionName) {
      throw new Error("collection.anki21b / collection.anki21 / collection.anki2 が見つからず、Ankiデッキとして認識できません。");
    }
    const modernPackage = collectionName === "collection.anki21b";
    const simulatorMarkerEntry = zip.get("apkg-simulator.json");
    let simulatorDeckId: string | undefined;
    if (simulatorMarkerEntry) {
      try {
        const markerBytes = await entryBytes(simulatorMarkerEntry, 65_536, "APKG Simulator識別情報");
        const marker = JSON.parse(new TextDecoder().decode(markerBytes)) as { formatVersion?: number; deckId?: string };
        if (marker.formatVersion === 1 && typeof marker.deckId === "string" && /^[a-zA-Z0-9_-]{1,80}$/.test(marker.deckId)) simulatorDeckId = marker.deckId;
      } catch { /* Optional marker failures fall back to ordinary APKG behavior. */ }
    }
    const collectionEntry = zip.get(collectionName);
    if (!collectionEntry) throw new Error("Ankiデータベースが見つかりません。");

    onProgress({ phase: "database", completed: 0, total: 1, message: "カードデータだけを取り出して解析しています" });
    let collectionBytes = await entryBytes(collectionEntry, MAX_DATABASE_BYTES, "カードデータベース");
    if (modernPackage) {
      try {
        collectionBytes = decompressZstd(collectionBytes, MAX_DATABASE_BYTES);
      } catch (error) {
        if (isMemoryError(error)) throw error;
        throw new Error("新しいAnki形式のカードデータを展開できません。.apkgが完全に保存されているか確認してください。");
      }
    }

    const hash = await deckFingerprint(collectionBytes, collectionName);
    const deckId = simulatorDeckId ?? hash.slice(0, 24);
    const completedDeck = await getDeck(deckId);
    if (completedDeck && !simulatorDeckId) {
      await deleteImportJob(deckId);
      const verifiedDeck = completedDeck.fileFingerprint === fileFingerprint
        ? completedDeck
        : { ...completedDeck, fileFingerprint };
      if (verifiedDeck !== completedDeck) await putDeck(verifiedDeck);
      return { deck: verifiedDeck, outcome: "existing" };
    }
    const mediaItems = await collectMediaItems(zip, modernPackage);
    const estimatedMediaBytes = mediaItems.reduce(
      (total, item) => total + (item.expectedSize ?? item.entry.uncompressedSize),
      0,
    );
    const SQL = await getSql();
    const db = new SQL.Database(collectionBytes);
    collectionBytes = new Uint8Array(0);
    let cardCount = 0;
    let deckName = baseName(file.name);
    let subdecks: SubdeckSummary[] = [];
    let resumed = false;
    try {
      let models: Record<string, AnkiModel>;
      let decks: Record<string, AnkiDeck>;
      if (modernPackage) {
        ({ models, decks } = modernModelsAndDecks(db));
      } else {
        const [modelsValue, decksValue] = firstRow(db, "SELECT models, decks FROM col LIMIT 1");
        models = parseJsonMap<AnkiModel>(modelsValue, "ノートタイプ");
        decks = parseJsonMap<AnkiDeck>(decksValue, "デッキ情報");
      }
      cardCount = Number(firstRow(db, "SELECT COUNT(*) FROM cards")[0]);
      if (!Number.isSafeInteger(cardCount) || cardCount <= 0) {
        throw new Error("演習できるカードが見つかりませんでした。");
      }

      const previousJob = await getImportJob(deckId);
      resumed = previousJob !== undefined && canResumeImport(
        previousJob,
        file,
        collectionName,
        cardCount,
        mediaItems.length,
        estimatedMediaBytes,
        fileFingerprint,
      );
      if (previousJob && !resumed) await deletePartialImport(deckId);

      const now = Date.now();
      const cardJob: ImportJobRecord = resumed && previousJob ? previousJob : {
        deckId,
        fileName: file.name,
        fileSize: file.size,
        fileFingerprint,
        sourceFormat: collectionName,
        cardCount,
        mediaCount: mediaItems.length,
        expectedMediaBytes: estimatedMediaBytes,
        nextCardIndex: 0,
        nextMediaIndex: 0,
        savedMediaBytes: 0,
        startedAt: now,
        updatedAt: now,
      };
      activeJob = cardJob;
      if (!resumed) await putImportJob(cardJob);

      const remainingCardBytes = Math.max(0, cardCount - cardJob.nextCardIndex) * 4096;
      const remainingMediaBytes = Math.max(0, estimatedMediaBytes - cardJob.savedMediaBytes);
      const warning = await storageCapacityWarning(remainingCardBytes + remainingMediaBytes);
      if (warning) {
        onProgress({
          phase: "opening",
          completed: 1,
          total: 1,
          message: resumed ? "保存済みの位置から読み込みを再開します" : "空き容量を確認して読み込みを続けます",
          warning,
        });
      }

      onProgress({
        phase: "cards",
        completed: cardJob.nextCardIndex,
        total: cardCount,
        message: resumed && cardJob.nextCardIndex
          ? `カードを途中から再開します（${cardJob.nextCardIndex.toLocaleString()} / ${cardCount.toLocaleString()}）`
          : `${cardCount.toLocaleString()}枚のカードを保存しています`,
      });
      const summary = await importCardsFromDatabase(
        db,
        file,
        deckId,
        models,
        decks,
        cardCount,
        cardJob,
        onProgress,
        (checkpoint) => { activeJob = checkpoint; },
      );
      activeJob = summary.job;
      deckName = summary.deckName;
      subdecks = summary.subdecks;
    } finally {
      db.close();
    }

    let mediaIndex = activeJob!.nextMediaIndex;
    let lastMediaYieldAt = performance.now();
    while (mediaIndex < mediaItems.length) {
      const batch: MediaRecord[] = [];
      let batchBytes = 0;
      while (mediaIndex < mediaItems.length && batch.length < MEDIA_BATCH_MAX_ITEMS) {
        const { entry, name, compressed, expectedSize } = mediaItems[mediaIndex];
        const blob = compressed
          ? await modernMediaBlob(entry, name, expectedSize)
          : await legacyMediaBlob(entry, name);
        batch.push({
          key: `${deckId}:${name}`,
          deckId,
          name,
          blob,
        });
        batchBytes += blob.size;
        mediaIndex += 1;
        if (batchBytes >= MEDIA_BATCH_MAX_BYTES) break;
      }
      const nextJob: ImportJobRecord = {
        ...activeJob!,
        nextMediaIndex: mediaIndex,
        savedMediaBytes: activeJob!.savedMediaBytes + batchBytes,
        updatedAt: Date.now(),
      };
      await putMediaBatchWithImportCheckpoint(batch, nextJob);
      activeJob = nextJob;
      onProgress({
        phase: "media",
        completed: mediaIndex,
        total: mediaItems.length,
        message: `画像・音声を保存しています（${mediaIndex.toLocaleString()} / ${mediaItems.length.toLocaleString()}）`,
      });
      lastMediaYieldAt = await yieldToBrowserIfNeeded(lastMediaYieldAt);
    }

    const deck: DeckRecord = {
      id: deckId,
      name: deckName,
      fileName: file.name,
      importedAt: Date.now(),
      cardCount,
      mediaCount: mediaItems.length,
      size: file.size,
      fileFingerprint,
      reviewCount: completedDeck?.reviewCount ?? 0,
      correctCount: completedDeck?.correctCount ?? 0,
      lastStudiedAt: completedDeck?.lastStudiedAt,
      sourceFormat: collectionName,
      subdecks,
    };
    onProgress({ phase: "saving", completed: 1, total: 1, message: "仕上げています" });
    await completeImport(deck);
    return { deck, outcome: resumed ? "resumed" : "imported" };
  } catch (error) {
    if (isQuotaError(error)) {
      const estimate = await navigator.storage?.estimate?.().catch(() => undefined);
      const available = estimate?.quota !== undefined && estimate.usage !== undefined
        ? Math.max(0, estimate.quota - estimate.usage)
        : undefined;
      const progress = activeJob
        ? activeJob.nextCardIndex < activeJob.cardCount
          ? `カード${activeJob.nextCardIndex.toLocaleString()} / ${activeJob.cardCount.toLocaleString()}枚まで保存済みです。`
          : `メディア${activeJob.nextMediaIndex.toLocaleString()} / ${activeJob.mediaCount.toLocaleString()}件まで保存済みです。`
        : "読み込み済みの途中データは保持されています。";
      throw new Error(`iPadの保存領域が不足しました。${available !== undefined ? `推定空き容量は約${formatBytes(available)}です。` : ""}${progress}空き容量を増やし、同じ.apkgを選ぶと続きから再開できます。`);
    }
    if (isMemoryError(error)) {
      throw new Error("iPadの作業メモリが不足しました。ほかのアプリとSafariタブを閉じて再試行してください。ファイル全体はメモリへ載せない方式ですが、カードDB単体の展開にはメモリが必要です。");
    }
    if (error instanceof Error && /malformed|not a database|database disk image|file is encrypted/i.test(error.message)) {
      throw new Error("APKG内のカードデータベースが破損しているか、未対応の形式です。AnkiからAPKGを再度書き出してください。");
    }
    if (error instanceof Error && /central directory|end of central|invalid zip|crc|zip signature|unexpected end/i.test(error.message)) {
      throw new Error("APKGのZIPデータが途中で切れているか破損しています。ファイルをiPadへコピーし直してください。");
    }
    if (error instanceof DOMException && ["AbortError", "InvalidStateError", "TransactionInactiveError", "UnknownError"].includes(error.name)) {
      throw new Error("iPad内への保存処理が中断されました。アプリを再起動し、同じAPKGを選ぶと保存済み位置から再開できます。");
    }
    throw error;
  } finally {
    await zipReader.close().catch(() => undefined);
  }
}
