export interface NavigatorPlatformInfo {
  userAgent?: string;
  platform?: string;
  maxTouchPoints?: number;
}

/** iPadOS 13+ can identify itself as Macintosh, so touch capability is needed. */
export function isIPadDevice(info: NavigatorPlatformInfo): boolean {
  if (/iPad/i.test(info.userAgent ?? "")) return true;
  return /MacIntel/i.test(info.platform ?? "") && (info.maxTouchPoints ?? 0) > 1;
}
