import type {
  DailyLimitSettings,
  DailyLimits,
  LearningPolicySettings,
  TodayOnlyLimitRecord,
} from "./types";

export const MAX_DAILY_LIMIT = 9_999;
export const DEFAULT_DAILY_LIMITS: DailyLimits = { newCards: 0, reviews: 0 };

export type DailyLimitKind = keyof DailyLimits;
export type DailyLimitSource = "common" | "deck" | "today";

export interface DailyLimitSessionResolution {
  overall: DailyLimits;
  sourceDeckLimits: ReadonlyMap<string, DailyLimits>;
  countFromParent: boolean;
}

export function normalizeDailyLimit(value: unknown): number {
  const number = Number(value);
  if (!Number.isFinite(number)) return 0;
  return Math.min(MAX_DAILY_LIMIT, Math.max(0, Math.round(number)));
}

function normalizeOverride(value: Partial<DailyLimits> | undefined): Partial<DailyLimits> {
  if (!value) return {};
  const normalized: Partial<DailyLimits> = {};
  if (Object.prototype.hasOwnProperty.call(value, "newCards")) normalized.newCards = normalizeDailyLimit(value.newCards);
  if (Object.prototype.hasOwnProperty.call(value, "reviews")) normalized.reviews = normalizeDailyLimit(value.reviews);
  return normalized;
}

export function dailyLimitScopeKey(deckId: string, sourceDeckId?: string): string {
  return sourceDeckId
    ? `${encodeURIComponent(deckId)}/${encodeURIComponent(sourceDeckId)}`
    : encodeURIComponent(deckId);
}

export function normalizeDailyLimitSettings(
  value: Partial<DailyLimitSettings> | undefined,
  legacyPolicy?: LearningPolicySettings,
): DailyLimitSettings {
  const common: DailyLimits = {
    newCards: normalizeDailyLimit(value?.common?.newCards ?? legacyPolicy?.dailyNewLimit ?? 0),
    reviews: normalizeDailyLimit(value?.common?.reviews ?? 0),
  };
  const deckOverrides = Object.fromEntries(Object.entries(value?.deckOverrides ?? {}).map(
    ([key, limits]) => [key, normalizeOverride(limits)],
  ));
  const subdeckOverrides = Object.fromEntries(Object.entries(value?.subdeckOverrides ?? {}).map(
    ([key, limits]) => [key, normalizeOverride(limits)],
  ));

  // v1.8 stored the new-card limit inside learningPolicy. Import it only
  // when the new daily-limit model has not already supplied that scope.
  if (!value) {
    for (const [deckId, policy] of Object.entries(legacyPolicy?.deckOverrides ?? {})) {
      deckOverrides[dailyLimitScopeKey(deckId)] = { newCards: normalizeDailyLimit(policy.dailyNewLimit) };
    }
    for (const [scopeKey, limit] of Object.entries(legacyPolicy?.subdeckDailyNewLimits ?? {})) {
      subdeckOverrides[scopeKey] = { newCards: normalizeDailyLimit(limit) };
    }
  }

  return {
    common,
    deckOverrides,
    subdeckOverrides,
    limitsStartFromTop: value?.limitsStartFromTop === true,
  };
}

export function permanentDailyLimitOverride(
  settings: DailyLimitSettings,
  deckId: string,
  sourceDeckId?: string,
): Partial<DailyLimits> | undefined {
  const key = dailyLimitScopeKey(deckId, sourceDeckId);
  return sourceDeckId ? settings.subdeckOverrides[key] : settings.deckOverrides[key];
}

export function permanentDailyLimits(
  settings: DailyLimitSettings,
  deckId: string,
  sourceDeckId?: string,
): DailyLimits {
  return { ...settings.common, ...permanentDailyLimitOverride(settings, deckId, sourceDeckId) };
}

export function activeTodayOnlyLimit(
  records: ReadonlyMap<string, TodayOnlyLimitRecord>,
  deckId: string,
  sourceDeckId: string | undefined,
  dayStartedAt: number,
): TodayOnlyLimitRecord | undefined {
  const record = records.get(dailyLimitScopeKey(deckId, sourceDeckId));
  return record?.dayStartedAt === dayStartedAt ? record : undefined;
}

export function effectiveDailyLimits(
  settings: DailyLimitSettings,
  records: ReadonlyMap<string, TodayOnlyLimitRecord>,
  deckId: string,
  sourceDeckId: string | undefined,
  dayStartedAt: number,
): DailyLimits {
  const permanent = permanentDailyLimits(settings, deckId, sourceDeckId);
  const today = activeTodayOnlyLimit(records, deckId, sourceDeckId, dayStartedAt);
  return {
    newCards: normalizeDailyLimit(today?.newCards ?? permanent.newCards),
    reviews: normalizeDailyLimit(today?.reviews ?? permanent.reviews),
  };
}

export function resolveDailyLimitSession(
  settings: DailyLimitSettings,
  records: ReadonlyMap<string, TodayOnlyLimitRecord>,
  deckId: string,
  sourceDeckId: string | undefined,
  sourceDeckIds: readonly string[],
  dayStartedAt: number,
): DailyLimitSessionResolution {
  if (sourceDeckId && !settings.limitsStartFromTop) {
    return {
      overall: effectiveDailyLimits(settings, records, deckId, sourceDeckId, dayStartedAt),
      sourceDeckLimits: new Map(),
      countFromParent: false,
    };
  }
  const candidates = sourceDeckId ? [sourceDeckId] : [...new Set(sourceDeckIds)];
  return {
    overall: effectiveDailyLimits(settings, records, deckId, undefined, dayStartedAt),
    sourceDeckLimits: new Map(candidates.map((candidate) => [
      candidate,
      effectiveDailyLimits(settings, records, deckId, candidate, dayStartedAt),
    ])),
    countFromParent: true,
  };
}

export function dailyLimitSource(
  settings: DailyLimitSettings,
  records: ReadonlyMap<string, TodayOnlyLimitRecord>,
  deckId: string,
  sourceDeckId: string | undefined,
  dayStartedAt: number,
  kind: DailyLimitKind,
): DailyLimitSource {
  const today = activeTodayOnlyLimit(records, deckId, sourceDeckId, dayStartedAt);
  if (today && Object.prototype.hasOwnProperty.call(today, kind)) return "today";
  const permanent = permanentDailyLimitOverride(settings, deckId, sourceDeckId);
  return permanent && Object.prototype.hasOwnProperty.call(permanent, kind) ? "deck" : "common";
}

export function withPermanentDailyLimit(
  settings: DailyLimitSettings,
  deckId: string,
  sourceDeckId: string | undefined,
  kind: DailyLimitKind,
  value: number | undefined,
): DailyLimitSettings {
  const output = structuredClone(settings);
  const collection = sourceDeckId ? output.subdeckOverrides : output.deckOverrides;
  const key = dailyLimitScopeKey(deckId, sourceDeckId);
  const current = { ...(collection[key] ?? {}) };
  if (value === undefined) delete current[kind];
  else current[kind] = normalizeDailyLimit(value);
  if (Object.keys(current).length) collection[key] = current;
  else delete collection[key];
  return output;
}

export function withTodayOnlyDailyLimit(
  current: TodayOnlyLimitRecord | undefined,
  deckId: string,
  sourceDeckId: string | undefined,
  dayStartedAt: number,
  kind: DailyLimitKind,
  value: number | undefined,
  updatedAt = Date.now(),
): TodayOnlyLimitRecord | undefined {
  const record: TodayOnlyLimitRecord = current?.dayStartedAt === dayStartedAt
    ? { ...current }
    : { scopeKey: dailyLimitScopeKey(deckId, sourceDeckId), deckId, sourceDeckId, dayStartedAt, updatedAt };
  if (value === undefined) delete record[kind];
  else record[kind] = normalizeDailyLimit(value);
  record.updatedAt = updatedAt;
  return record.newCards === undefined && record.reviews === undefined ? undefined : record;
}
