import type { CardRecord, DeckOptionPreset, Grade, LearningPolicySettings, ProgressRecord, ReviewInterval, ReviewTiming, SavedSessionRecord, SessionOptions, SessionSummary } from "./types";
import {
  DEFAULT_DAY_START_MINUTES,
  DEFAULT_LOOKAHEAD_MINUTES,
  DEFAULT_REVIEW_INTERVALS,
  dueAtForGrade,
  nextStudyDayStart,
  progressDueAt,
} from "./scheduler";
import { coverageFirstCards, limitDailyNewCards, limitDailyReviewCards, reviewFirstCards, separateSiblingCards } from "./queuePolicy";
import { DEFAULT_LEARNING_POLICY } from "./learningPolicy";
import { isReviewLapse, previewSm2Answers, scheduleSm2Answer } from "./sm2Scheduler";

interface SessionEvent {
  card: CardRecord;
  position: number;
  insertedAt?: number;
  dueAt?: number;
  availableAfterReviewCount?: number;
  grade: Grade;
  previousProgress?: ProgressRecord;
  nextProgress?: ProgressRecord;
  buriedCardIds?: string[];
}

interface ScheduledCard {
  card: CardRecord;
  dueAt: number;
  availableAfterReviewCount?: number;
}

function shuffle<T>(values: T[]): T[] {
  const output = [...values];
  for (let index = output.length - 1; index > 0; index -= 1) {
    const target = Math.floor(Math.random() * (index + 1));
    [output[index], output[target]] = [output[target], output[index]];
  }
  return output;
}

export class StudySession {
  private queue: CardRecord[];
  private position = 0;
  private events: SessionEvent[] = [];
  private scheduled: ScheduledCard[] = [];
  private progress: Map<string, ProgressRecord>;
  private cardsById: Map<string, CardRecord>;
  private startedAt = Date.now();
  private counts: Record<Grade, number> = { again: 0, hard: 0, good: 0, easy: 0 };
  private reviewTiming: ReviewTiming;
  private learningPolicy: LearningPolicySettings;
  private deferredNewCardCount = 0;
  private deferredReviewCardCount = 0;
  private sourceDeckDailyNewLimits: ReadonlyMap<string, number>;
  private dailyReviewLimit: number;
  private sourceDeckDailyReviewLimits: ReadonlyMap<string, number>;
  private reviewCardIds: ReadonlySet<string>;
  private reviewedToday: Set<string>;
  private admittedReviewCardIds = new Set<string>();
  private cardSourceDeckIds: ReadonlyMap<string, string>;
  private introducedBySourceDeck: ReadonlyMap<string, number>;
  private reviewedBySourceDeck: ReadonlyMap<string, number>;
  readonly initialCount: number;

  constructor(
    cards: CardRecord[],
    progressRecords: ProgressRecord[],
    options: SessionOptions,
    saved?: SavedSessionRecord,
    flaggedCardIds: ReadonlySet<string> = new Set(),
    reviewTiming: ReviewTiming = {
      intervals: DEFAULT_REVIEW_INTERVALS,
      dayStartMinutes: DEFAULT_DAY_START_MINUTES,
      lookaheadMinutes: DEFAULT_LOOKAHEAD_MINUTES,
    },
    learningPolicy: LearningPolicySettings = DEFAULT_LEARNING_POLICY,
    introducedNewCardIds: ReadonlySet<string> = new Set(),
    sourceDeckDailyNewLimits: ReadonlyMap<string, number> = new Map(),
    reviewCardIds: ReadonlySet<string> = new Set(),
    reviewedToday: ReadonlySet<string> = new Set(),
    dailyReviewLimit = 0,
    sourceDeckDailyReviewLimits: ReadonlyMap<string, number> = new Map(),
  ) {
    this.reviewTiming = reviewTiming;
    this.learningPolicy = learningPolicy;
    this.sourceDeckDailyNewLimits = sourceDeckDailyNewLimits;
    this.reviewCardIds = reviewCardIds;
    this.reviewedToday = new Set(reviewedToday);
    this.dailyReviewLimit = dailyReviewLimit;
    this.sourceDeckDailyReviewLimits = sourceDeckDailyReviewLimits;
    this.cardSourceDeckIds = new Map(cards.map((card) => [card.id, card.sourceDeckId]));
    this.cardsById = new Map(cards.map((card) => [card.id, card]));
    const introducedBySourceDeck = new Map<string, number>();
    for (const card of cards) {
      if (!introducedNewCardIds.has(card.id)) continue;
      introducedBySourceDeck.set(card.sourceDeckId, (introducedBySourceDeck.get(card.sourceDeckId) ?? 0) + 1);
    }
    this.introducedBySourceDeck = introducedBySourceDeck;
    const reviewedBySourceDeck = new Map<string, number>();
    for (const card of cards) {
      if (!reviewedToday.has(card.id)) continue;
      reviewedBySourceDeck.set(card.sourceDeckId, (reviewedBySourceDeck.get(card.sourceDeckId) ?? 0) + 1);
    }
    this.reviewedBySourceDeck = reviewedBySourceDeck;
    const progress = new Map(progressRecords.map((item) => [item.cardId, item]));
    this.progress = progress;
    if (saved) {
      const cardsById = new Map(cards.map((card) => [card.id, card]));
      const restoredQueue = saved.cardIds.map((id) => cardsById.get(id));
      if (restoredQueue.every((card): card is CardRecord => Boolean(card))) {
        this.queue = restoredQueue;
        this.position = Math.min(saved.position, this.queue.length);
        this.events = saved.events.flatMap((event) => {
          const card = cardsById.get(event.cardId);
          return card ? [{ ...event, card }] : [];
        });
        if (saved.scheduled) {
          this.scheduled = saved.scheduled.flatMap((item) => {
            const card = cardsById.get(item.cardId);
            return card ? [{ card, dueAt: item.dueAt, availableAfterReviewCount: item.availableAfterReviewCount }] : [];
          });
        } else {
          // v9.1以前の「数枚後」キューを、保存済み回答時刻を使った時間制へ移行する。
          const insertedIndexes = this.events
            .flatMap((event) => event.insertedAt === undefined ? [] : [event.insertedAt])
            .sort((a, b) => b - a);
          for (const insertedAt of insertedIndexes) {
            this.queue.splice(insertedAt, 1);
            if (insertedAt < this.position) this.position = Math.max(0, this.position - 1);
          }
          const scheduledCards = new Set<string>();
          for (const event of [...this.events].reverse()) {
            event.insertedAt = undefined;
            if (scheduledCards.has(event.card.id)) continue;
            const state = progress.get(event.card.id);
            event.dueAt = state
              ? progressDueAt(state)
              : dueAtForGrade(event.grade, saved.updatedAt, this.reviewTiming.intervals, this.reviewTiming.dayStartMinutes);
            this.scheduled.push({ card: event.card, dueAt: event.dueAt });
            scheduledCards.add(event.card.id);
          }
        }
        const suspendedCardIds = new Set(cards
          .filter((card) => card.suspended || progress.get(card.id)?.schedulerState?.suspended)
          .map((card) => card.id));
        this.excludeCardIds(suspendedCardIds);
        this.counts = { ...saved.counts };
        this.initialCount = saved.initialCount;
        this.startedAt = saved.startedAt;
        this.refreshDueCards();
        this.applyDailyNewLimit(introducedNewCardIds, this.position);
        this.applyDailyReviewLimit(this.position);
        this.applyReviewLimitToNewCards(this.position);
        return;
      }
    }

    const now = Date.now();
    let filtered = cards.filter((card) => {
      const state = progress.get(card.id);
      if (card.suspended || state?.schedulerState?.suspended) return false;
      const isDue = state ? progressDueAt(state) <= now : true;
      if (options.filter === "flagged") return flaggedCardIds.has(card.id);
      if (options.filter === "unseen") return !state || isDue;
      if (options.filter === "missed") return isDue && (state?.lastGrade === "again" || state?.lastGrade === "hard");
      return true;
    });
    if (options.filter !== "all" && options.filter !== "flagged") {
      this.scheduled = cards.flatMap((card) => {
        if (card.suspended) return [];
        const state = progress.get(card.id);
        if (!state) return [];
        const dueAt = progressDueAt(state);
        const matchesFilter = options.filter === "unseen"
          || state.lastGrade === "again"
          || state.lastGrade === "hard";
        return dueAt > now && matchesFilter ? [{ card, dueAt }] : [];
      });
    }
    if (options.order === "shuffle") filtered = shuffle(filtered);
    if (this.reviewTiming.scheduler) {
      filtered = this.orderForScheduler(filtered);
    } else if (this.learningPolicy.priorityMode === "unseen" || (
      this.learningPolicy.priorityMode === "balanced" && (options.sprintMinutes ?? 0) > 0
    )) {
      filtered = coverageFirstCards(filtered, progress);
    } else if (this.learningPolicy.priorityMode === "review") {
      filtered = reviewFirstCards(filtered, progress);
    }
    const dailyLimited = limitDailyNewCards(
      filtered,
      progress,
      introducedNewCardIds,
      this.learningPolicy.dailyNewLimit,
      this.sourceDeckDailyNewLimits,
      this.introducedBySourceDeck,
    );
    filtered = dailyLimited.cards;
    this.deferredNewCardCount = dailyLimited.deferredCardIds.length;
    if (this.learningPolicy.siblingGuard) filtered = separateSiblingCards(filtered);
    this.queue = filtered;
    this.applyDailyReviewLimit(0);
    this.applyReviewLimitToNewCards(0);
    this.queue = this.queue.slice(0, options.limit > 0 ? options.limit : undefined);
    if (!this.queue.length) this.refreshDueCards(now);
    this.initialCount = this.queue.length;
  }

  private schedulerForCard(card: CardRecord): DeckOptionPreset | undefined {
    return this.reviewTiming.sourceDeckSchedulers?.[card.sourceDeckId] ?? this.reviewTiming.scheduler;
  }

  private orderForScheduler(cards: CardRecord[]): CardRecord[] {
    const options = this.reviewTiming.scheduler;
    if (!options) return cards;
    let newCards = cards.filter((card) => !this.progress.has(card.id));
    const interday = cards.filter((card) => {
      const state = this.progress.get(card.id)?.schedulerState;
      return state?.phase === "learning" || state?.phase === "relearning";
    });
    const reviews = cards.filter((card) => {
      const state = this.progress.get(card.id)?.schedulerState;
      return this.progress.has(card.id) && state?.phase !== "learning" && state?.phase !== "relearning";
    });
    if (options.newCardGatherOrder === "deck") newCards.sort((a, b) => a.sourceDeckId.localeCompare(b.sourceDeckId, undefined, { numeric: true }));
    else if (options.newCardGatherOrder === "deckReverse") newCards.sort((a, b) => b.sourceDeckId.localeCompare(a.sourceDeckId, undefined, { numeric: true }));
    else if (options.newCardGatherOrder === "positionAsc") newCards.sort((a, b) => a.id.localeCompare(b.id, undefined, { numeric: true }));
    else if (options.newCardGatherOrder === "positionDesc") newCards.sort((a, b) => b.id.localeCompare(a.id, undefined, { numeric: true }));
    else if (options.newCardGatherOrder === "randomNotes") {
      const noteOrder = new Map(shuffle([...new Set(newCards.map((card) => card.noteId))]).map((id, index) => [id, index]));
      newCards.sort((a, b) => (noteOrder.get(a.noteId) ?? 0) - (noteOrder.get(b.noteId) ?? 0));
    } else if (options.newCardGatherOrder === "randomCards") newCards = shuffle(newCards);
    if (options.newCardSortOrder === "cardType") newCards.sort((a, b) => a.ordinal - b.ordinal);
    else if (options.newCardSortOrder === "cardTypeRandom") {
      newCards = shuffle(newCards).sort((a, b) => a.ordinal - b.ordinal);
    } else if (options.newCardSortOrder === "randomNotes") {
      const noteOrder = new Map(shuffle([...new Set(newCards.map((card) => card.noteId))]).map((id, index) => [id, index]));
      newCards.sort((a, b) => (noteOrder.get(a.noteId) ?? 0) - (noteOrder.get(b.noteId) ?? 0));
    } else if (options.newCardSortOrder === "randomCards" || options.newCardInsertionOrder === "random") newCards = shuffle(newCards);
    const orderedReviews = [...reviews].sort((a, b) => {
      const left = this.progress.get(a.id)!;
      const right = this.progress.get(b.id)!;
      const leftState = left.schedulerState;
      const rightState = right.schedulerState;
      switch (options.reviewOrder) {
        case "random": return Math.random() - 0.5;
        case "overdue": {
          const now = Date.now();
          const leftRatio = Math.max(0, now - progressDueAt(left)) / Math.max(1, (leftState?.intervalDays ?? 1) * 86_400_000);
          const rightRatio = Math.max(0, now - progressDueAt(right)) / Math.max(1, (rightState?.intervalDays ?? 1) * 86_400_000);
          return rightRatio - leftRatio;
        }
        case "intervalAsc": return (leftState?.intervalDays ?? 0) - (rightState?.intervalDays ?? 0);
        case "intervalDesc": return (rightState?.intervalDays ?? 0) - (leftState?.intervalDays ?? 0);
        case "easeAsc": return (leftState?.easeFactor ?? 2.5) - (rightState?.easeFactor ?? 2.5);
        case "easeDesc": return (rightState?.easeFactor ?? 2.5) - (leftState?.easeFactor ?? 2.5);
        default: return progressDueAt(left) - progressDueAt(right);
      }
    });
    let reviewStream: CardRecord[];
    if (options.interdayLearningOrder === "before") reviewStream = [...interday, ...orderedReviews];
    else if (options.interdayLearningOrder === "after") reviewStream = [...orderedReviews, ...interday];
    else {
      reviewStream = [];
      const maximum = Math.max(interday.length, orderedReviews.length);
      for (let index = 0; index < maximum; index += 1) {
        if (interday[index]) reviewStream.push(interday[index]);
        if (orderedReviews[index]) reviewStream.push(orderedReviews[index]);
      }
    }
    if (options.newReviewOrder === "before") return [...newCards, ...reviewStream];
    if (options.newReviewOrder === "after") return [...reviewStream, ...newCards];
    const mixed: CardRecord[] = [];
    const maximum = Math.max(newCards.length, reviewStream.length);
    for (let index = 0; index < maximum; index += 1) {
      if (reviewStream[index]) mixed.push(reviewStream[index]);
      if (newCards[index]) mixed.push(newCards[index]);
    }
    return mixed;
  }

  get current(): CardRecord | undefined {
    return this.queue[this.position];
  }

  isNewCard(cardId: string): boolean {
    return !this.progress.has(cardId);
  }

  get deferredNewCards(): number {
    return this.deferredNewCardCount;
  }

  get deferredReviewCards(): number {
    return this.deferredReviewCardCount;
  }

  isReviewCard(cardId: string): boolean {
    return this.reviewCardIds.has(cardId);
  }

  markCardShown(cardId: string): void {
    if (this.reviewCardIds.has(cardId)) this.reviewedToday.add(cardId);
  }

  private applyDailyNewLimit(introducedNewCardIds: ReadonlySet<string>, fromIndex: number): void {
    if (
      (this.learningPolicy.dailyNewLimit <= 0 && ![...this.sourceDeckDailyNewLimits.values()].some((limit) => limit > 0))
      || fromIndex >= this.queue.length
    ) return;
    const remaining = this.queue.slice(fromIndex);
    const limited = limitDailyNewCards(
      remaining,
      this.progress,
      introducedNewCardIds,
      this.learningPolicy.dailyNewLimit,
      this.sourceDeckDailyNewLimits,
      this.introducedBySourceDeck,
    );
    if (!limited.deferredCardIds.length) return;
    const deferred = new Set(limited.deferredCardIds);
    const removedIndexes = this.queue.flatMap((card, index) => (
      index >= fromIndex && deferred.has(card.id) && !this.progress.has(card.id) ? [index] : []
    ));
    this.queue = this.queue.filter((_card, index) => !removedIndexes.includes(index));
    for (const event of this.events) {
      if (event.insertedAt === undefined) continue;
      event.insertedAt -= removedIndexes.filter((index) => index < event.insertedAt!).length;
    }
    this.deferredNewCardCount = removedIndexes.length;
  }

  private applyDailyReviewLimit(fromIndex: number): void {
    if (
      (this.dailyReviewLimit <= 0 && ![...this.sourceDeckDailyReviewLimits.values()].some((limit) => limit > 0))
      || fromIndex >= this.queue.length
    ) return;
    const remaining = this.queue.slice(fromIndex);
    const limited = limitDailyReviewCards(
      remaining,
      this.reviewCardIds,
      this.reviewedToday,
      this.dailyReviewLimit,
      this.sourceDeckDailyReviewLimits,
      this.reviewedBySourceDeck,
    );
    for (const card of limited.cards) {
      if (this.reviewCardIds.has(card.id) && !this.reviewedToday.has(card.id)) {
        this.admittedReviewCardIds.add(card.id);
      }
    }
    if (!limited.deferredCardIds.length) return;
    const deferred = new Set(limited.deferredCardIds);
    const removedIndexes = this.queue.flatMap((card, index) => (
      index >= fromIndex && deferred.has(card.id) && this.reviewCardIds.has(card.id) ? [index] : []
    ));
    this.queue = this.queue.filter((_card, index) => !removedIndexes.includes(index));
    for (const event of this.events) {
      if (event.insertedAt === undefined) continue;
      event.insertedAt -= removedIndexes.filter((index) => index < event.insertedAt!).length;
    }
    this.scheduled = this.scheduled.filter((item) => !deferred.has(item.card.id));
    this.deferredReviewCardCount = removedIndexes.length;
  }

  private applyReviewLimitToNewCards(fromIndex: number): void {
    const options = this.reviewTiming.scheduler;
    if (!options || options.newCardsIgnoreReviewLimit || this.dailyReviewLimit <= 0 || fromIndex >= this.queue.length) return;
    const reservedReviewIds = new Set(this.queue.slice(fromIndex)
      .filter((card) => this.reviewCardIds.has(card.id))
      .map((card) => card.id));
    const used = new Set([...this.reviewedToday, ...reservedReviewIds]).size;
    let availableNewSlots = Math.max(0, this.dailyReviewLimit - used);
    const removed = new Set<string>();
    for (const card of this.queue.slice(fromIndex)) {
      if (this.progress.has(card.id)) continue;
      if (availableNewSlots > 0) availableNewSlots -= 1;
      else removed.add(card.id);
    }
    if (!removed.size) return;
    this.queue = this.queue.filter((card, index) => index < fromIndex || !removed.has(card.id));
    this.deferredNewCardCount += removed.size;
  }

  peek(offset = 1): CardRecord | undefined {
    return this.queue[this.position + offset];
  }

  excludeCardIds(cardIds: ReadonlySet<string>): number {
    if (!cardIds.size) return 0;
    const removedIndexes = this.queue.flatMap((card, index) => cardIds.has(card.id) ? [index] : []);
    if (!removedIndexes.length) return 0;
    const removedBeforePosition = removedIndexes.filter((index) => index < this.position).length;
    this.queue = this.queue.filter((card) => !cardIds.has(card.id));
    this.position = Math.max(0, this.position - removedBeforePosition);
    this.scheduled = this.scheduled.filter((item) => !cardIds.has(item.card.id));
    for (const event of this.events) {
      if (event.insertedAt === undefined) continue;
      if (removedIndexes.includes(event.insertedAt)) {
        event.insertedAt = undefined;
        continue;
      }
      event.insertedAt -= removedIndexes.filter((index) => index < event.insertedAt!).length;
    }
    return removedIndexes.length;
  }

  dismissCurrent(): CardRecord | undefined {
    const card = this.current;
    if (!card) return undefined;
    this.excludeCardIds(new Set([card.id]));
    return card;
  }

  restoreDismissedCurrent(card: CardRecord): boolean {
    if (this.queue.some((queued) => queued.id === card.id)) return false;
    if (this.scheduled.some((scheduled) => scheduled.card.id === card.id)) return false;
    this.queue.splice(this.position, 0, card);
    return true;
  }

  get remaining(): number {
    return Math.max(0, this.queue.length - this.position);
  }

  get reviewed(): number {
    return this.events.length;
  }

  get newRemaining(): number {
    const answeredCardIds = new Set(this.events.map((event) => event.card.id));
    return new Set(this.queue.slice(this.position)
      .filter((card) => !this.progress.has(card.id) && !answeredCardIds.has(card.id))
      .map((card) => card.id)).size;
  }

  get incorrectScheduled(): number {
    const latestGrade = new Map([...this.progress].map(([cardId, state]) => [cardId, state.lastGrade]));
    for (const event of this.events) latestGrade.set(event.card.id, event.grade);
    return new Set(this.scheduled
      .filter((item) => latestGrade.get(item.card.id) === "again")
      .map((item) => item.card.id)).size;
  }

  get complete(): boolean {
    return this.position >= this.queue.length;
  }

  get nextDueAt(): number | undefined {
    return this.scheduled.reduce<number | undefined>(
      (earliest, item) => earliest === undefined || item.dueAt < earliest ? item.dueAt : earliest,
      undefined,
    );
  }

  setReviewTiming(reviewTiming: ReviewTiming): void {
    this.reviewTiming = reviewTiming;
  }

  answerIntervals(reviewedAt = Date.now()): Record<Grade, ReviewInterval> {
    const card = this.current;
    const scheduler = card ? this.schedulerForCard(card) : undefined;
    if (!card || !scheduler) return this.reviewTiming.intervals;
    const previews = previewSm2Answers(this.progress.get(card.id), scheduler, reviewedAt, this.reviewTiming.dayStartMinutes, card.id);
    return {
      again: previews.again.interval,
      hard: previews.hard.interval,
      good: previews.good.interval,
      easy: previews.easy.interval,
    };
  }

  refreshDueCards(now = Date.now()): boolean {
    const isIdle = this.position >= this.queue.length;
    const threshold = isIdle
      ? now + this.reviewTiming.lookaheadMinutes * 60 * 1000
      : now;
    let ready = this.scheduled.filter((item) => (
      item.dueAt <= threshold
      && (isIdle || item.availableAfterReviewCount === undefined || this.events.length >= item.availableAfterReviewCount)
    )).sort((a, b) => a.dueAt - b.dueAt);
    if (ready.length && (this.dailyReviewLimit > 0 || [...this.sourceDeckDailyReviewLimits.values()].some((limit) => limit > 0))) {
      const reservedReviewIds = new Set([...this.reviewedToday, ...this.admittedReviewCardIds]);
      const reservedBySourceDeck = new Map<string, number>();
      for (const cardId of reservedReviewIds) {
        const sourceDeckId = this.cardSourceDeckIds.get(cardId);
        if (sourceDeckId) reservedBySourceDeck.set(sourceDeckId, (reservedBySourceDeck.get(sourceDeckId) ?? 0) + 1);
      }
      const limited = limitDailyReviewCards(
        ready.map((item) => item.card),
        this.reviewCardIds,
        reservedReviewIds,
        this.dailyReviewLimit,
        this.sourceDeckDailyReviewLimits,
        reservedBySourceDeck,
      );
      const included = new Set(limited.cards.map((card) => card.id));
      ready = ready.filter((item) => included.has(item.card.id));
      for (const card of limited.cards) {
        if (this.reviewCardIds.has(card.id) && !reservedReviewIds.has(card.id)) this.admittedReviewCardIds.add(card.id);
      }
      this.deferredReviewCardCount = Math.max(this.deferredReviewCardCount, limited.deferredCardIds.length);
    }
    if (!ready.length) return false;
    const readyItems = new Set(ready);
    this.scheduled = this.scheduled.filter((item) => !readyItems.has(item));
    ready.forEach((item, offset) => {
      const sourceEvent = [...this.events].reverse().find((event) =>
        event.card.id === item.card.id && event.dueAt === item.dueAt && event.insertedAt === undefined,
      );
      if (sourceEvent) sourceEvent.insertedAt = this.position + offset;
    });
    this.queue.splice(this.position, 0, ...ready.map((item) => item.card));
    return true;
  }

  grade(grade: Grade, reviewedAt = Date.now()): SessionEvent | undefined {
    const card = this.current;
    if (!card) return undefined;
    const previousProgress = this.progress.get(card.id);
    const scheduler = this.schedulerForCard(card);
    const scheduled = scheduler
      ? scheduleSm2Answer(previousProgress, grade, scheduler, reviewedAt, this.reviewTiming.dayStartMinutes, card.id)
      : undefined;
    const dueAt = scheduled?.dueAt ?? dueAtForGrade(grade, reviewedAt, this.reviewTiming.intervals, this.reviewTiming.dayStartMinutes);
    const isCorrect = grade === "good" || grade === "easy";
    const nextProgress: ProgressRecord = {
      key: `${card.deckId}:${card.id}`,
      deckId: card.deckId,
      cardId: card.id,
      lastGrade: grade,
      reviewCount: (previousProgress?.reviewCount ?? 0) + 1,
      correctCount: (previousProgress?.correctCount ?? 0) + (isCorrect ? 1 : 0),
      lapseCount: (previousProgress?.lapseCount ?? 0) + (isReviewLapse(previousProgress, grade) ? 1 : 0),
      lastReviewedAt: reviewedAt,
      firstReviewedAt: previousProgress?.firstReviewedAt ?? reviewedAt,
      dueAt,
      schedulerState: scheduled?.state,
    };
    const buriedCardIds = scheduler ? this.siblingIdsToBury(card, previousProgress, scheduler) : [];
    const availableAfterReviewCount = this.events.length + 1 + this.learningPolicy.minimumInterveningCards;
    const event: SessionEvent = {
      card,
      position: this.position,
      dueAt,
      availableAfterReviewCount,
      grade,
      previousProgress: previousProgress ? { ...previousProgress, schedulerState: previousProgress.schedulerState ? { ...previousProgress.schedulerState } : undefined } : undefined,
      nextProgress,
      buriedCardIds,
    };
    this.position += 1;
    this.progress.set(card.id, nextProgress);
    if (buriedCardIds.length) this.excludeCardIds(new Set(buriedCardIds));
    if (!nextProgress.schedulerState?.suspended) this.scheduled.push({ card, dueAt, availableAfterReviewCount });
    this.counts[grade] += 1;
    this.events.push(event);
    this.refreshDueCards(reviewedAt);
    return event;
  }

  private siblingIdsToBury(card: CardRecord, progress: ProgressRecord | undefined, options: DeckOptionPreset): string[] {
    const answeredState = progress?.schedulerState;
    const answeredIsNew = !progress;
    const answeredIsInterday = Boolean(answeredState && answeredState.phase !== "review" && progress?.dueAt
      && progress.dueAt >= nextStudyDayStart(progress.lastReviewedAt, this.reviewTiming.dayStartMinutes));
    const enabled = answeredIsNew
      ? options.buryNewSiblings
      : answeredIsInterday ? options.buryInterdayLearningSiblings : options.buryReviewSiblings;
    if (!enabled) return [];
    return this.queue.slice(this.position + 1)
      .filter((candidate) => candidate.noteId === card.noteId && candidate.id !== card.id)
      .map((candidate) => candidate.id);
  }

  undo(): SessionEvent | undefined {
    const event = this.events.pop();
    if (!event) return undefined;
    if (event.insertedAt !== undefined) this.queue.splice(event.insertedAt, 1);
    if (event.dueAt !== undefined) {
      const scheduledIndex = this.scheduled.findIndex((item) => item.card.id === event.card.id && item.dueAt === event.dueAt);
      if (scheduledIndex >= 0) this.scheduled.splice(scheduledIndex, 1);
    }
    this.position = event.position;
    if (event.previousProgress) this.progress.set(event.card.id, event.previousProgress);
    else this.progress.delete(event.card.id);
    if (event.buriedCardIds?.length) {
      const restored = event.buriedCardIds.flatMap((cardId) => {
        const card = this.cardsById.get(cardId);
        return card ? [card] : [];
      });
      this.queue.splice(this.position + 1, 0, ...restored);
    }
    this.counts[event.grade] = Math.max(0, this.counts[event.grade] - 1);
    return event;
  }

  restoreUndone(event: SessionEvent): void {
    this.position = event.position + 1;
    this.counts[event.grade] += 1;
    this.events.push(event);
    if (event.nextProgress) this.progress.set(event.card.id, event.nextProgress);
    if (event.insertedAt !== undefined) {
      this.queue.splice(event.insertedAt, 0, event.card);
    } else if (event.dueAt !== undefined) {
      this.scheduled.push({
        card: event.card,
        dueAt: event.dueAt,
        availableAfterReviewCount: event.availableAfterReviewCount,
      });
    }
  }

  snapshot(deckId: string, options: SessionOptions, sourceDeckId?: string): SavedSessionRecord {
    return {
      deckId,
      sourceDeckId,
      options: { ...options },
      cardIds: this.queue.map((card) => card.id),
      position: this.position,
      events: this.events.map(({ card, ...event }) => ({
        ...event,
        cardId: card.id,
        previousProgress: event.previousProgress ? { ...event.previousProgress, schedulerState: event.previousProgress.schedulerState ? { ...event.previousProgress.schedulerState } : undefined } : undefined,
        nextProgress: event.nextProgress ? { ...event.nextProgress, schedulerState: event.nextProgress.schedulerState ? { ...event.nextProgress.schedulerState } : undefined } : undefined,
        buriedCardIds: event.buriedCardIds ? [...event.buriedCardIds] : undefined,
      })),
      counts: { ...this.counts },
      initialCount: this.initialCount,
      startedAt: this.startedAt,
      updatedAt: Date.now(),
      scheduled: this.scheduled.map(({ card, dueAt, availableAfterReviewCount }) => ({
        cardId: card.id,
        dueAt,
        availableAfterReviewCount,
      })),
    };
  }

  summary(): SessionSummary {
    return {
      reviewed: this.events.length,
      ...this.counts,
      elapsedMs: Math.max(0, Date.now() - this.startedAt),
    };
  }
}
