export type DatabaseIntegritySeverity = "warning" | "error";

export interface DeckIntegritySnapshot {
  deckId: string;
  deckName: string;
  storedCardCount: number;
  actualCardCount: number;
  storedMediaCount: number;
  actualMediaCount: number;
  storedReviewCount: number;
  actualReviewCount: number;
  storedCorrectCount: number;
  actualCorrectCount: number;
  progressReviewCount: number;
  progressCorrectCount: number;
}

export interface DatabaseIntegrityIssue {
  code: "card-count" | "media-count" | "review-count" | "correct-count" | "progress-review-count" | "progress-correct-count" | "orphan-session";
  severity: DatabaseIntegritySeverity;
  deckId: string;
  deckName: string;
  message: string;
  repairable: boolean;
}

export interface DatabaseIntegrityReport {
  checkedAt: number;
  databaseVersion: number;
  deckCount: number;
  cardCount: number;
  mediaCount: number;
  reviewCount: number;
  progressCount: number;
  issues: DatabaseIntegrityIssue[];
  decks: DeckIntegritySnapshot[];
}

export function deckIntegrityIssues(snapshot: DeckIntegritySnapshot): DatabaseIntegrityIssue[] {
  const base = { deckId: snapshot.deckId, deckName: snapshot.deckName };
  const issues: DatabaseIntegrityIssue[] = [];
  const compare = (
    code: DatabaseIntegrityIssue["code"],
    label: string,
    stored: number,
    actual: number,
    repairable: boolean,
  ): void => {
    if (stored === actual) return;
    issues.push({
      ...base,
      code,
      severity: repairable ? "warning" : "error",
      message: `${label}: 記録${stored.toLocaleString()} / 実データ${actual.toLocaleString()}`,
      repairable,
    });
  };
  compare("card-count", "カード枚数", snapshot.storedCardCount, snapshot.actualCardCount, true);
  compare("media-count", "メディア件数", snapshot.storedMediaCount, snapshot.actualMediaCount, true);
  compare("review-count", "回答回数", snapshot.storedReviewCount, snapshot.actualReviewCount, true);
  compare("correct-count", "正解回数", snapshot.storedCorrectCount, snapshot.actualCorrectCount, true);
  compare("progress-review-count", "進捗と回答履歴の回数", snapshot.progressReviewCount, snapshot.actualReviewCount, false);
  compare("progress-correct-count", "進捗と回答履歴の正解数", snapshot.progressCorrectCount, snapshot.actualCorrectCount, false);
  return issues;
}
